window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-034"]={"PYCARD":{"hgnc":"HGNC:16608","symbol":"PYCARD","accessions":["Q9ULZ3"],"name":"Apoptosis-associated speck-like protein containing a CARD","length":"195","function":"Functions as a key mediator in apoptosis and inflammation (PubMed:11103777, PubMed:12646168, PubMed:15030775, PubMed:17349957, PubMed:17599095, PubMed:19158675, PubMed:19158676, PubMed:19234215, PubMed:19494289, PubMed:21487011, PubMed:24630722, PubMed:25847972, PubMed:30674671, PubMed:34678144, PubMed:36050480). Promotes caspase-mediated apoptosis involving predominantly caspase-8 and also caspase-9 in a probable cell type-specific manner (PubMed:11103777, PubMed:12646168). Involved in activation of the mitochondrial apoptotic pathway, promotes caspase-8-dependent proteolytic maturation of BID independently of FADD in certain cell types and also mediates mitochondrial translocation of BAX and activates BAX-dependent apoptosis coupled to activation of caspase-9, -2 and -3 (PubMed:14730312, PubMed:16964285). Involved in innate immune response by acting as an integral adapter in the assembly of various inflammasomes (NLRP1, NLRP2, NLRP3, NLRP6, AIM2 and probably IFI16) which recruit and activate caspase-1 leading to processing and secretion of pro-inflammatory cytokines (PubMed:15030775, PubMed:16982856, PubMed:17349957, PubMed:17599095, PubMed:19158675, PubMed:19158676, PubMed:19234215, PubMed:21487011, PubMed:23530044, PubMed:24630722, PubMed:25847972, PubMed:29440442, PubMed:30674671, PubMed:33980849, PubMed:34678144, PubMed:34706239). Caspase-1-dependent inflammation leads to macrophage pyroptosis, a form of cell death (PubMed:24630722). The function as activating adapter in different types of inflammasomes is mediated by the pyrin and CARD domains and their homotypic interactions (PubMed:14499617, PubMed:19234215, PubMed:24630722). Clustered PYCARD nucleates the formation of caspase-1 filaments through the interaction of their respective CARD domains, acting as a platform for of caspase-1 polymerization (PubMed:24630722). In the NLRP1 and NLRC4 inflammasomes seems not be required but facilitates the processing of procaspase-1 (PubMed:17349957). In cooperation with NOD2 involved in an inflammasome activated by bacterial muramyl dipeptide leading to caspase-1 activation (PubMed:16964285). May be involved in RIGI-triggered pro-inflammatory responses and inflammasome activation (PubMed:19915568). In collaboration with AIM2 which detects cytosolic double-stranded DNA may also be involved in a caspase-1-independent cell death that involves caspase-8 (PubMed:19158675, PubMed:19158676). In adaptive immunity may be involved in maturation of dendritic cells to stimulate T-cell immunity and in cytoskeletal rearrangements coupled to chemotaxis and antigen uptake may be involved in post-transcriptional regulation of the guanine nucleotide exchange factor DOCK2; the latter function is proposed to involve the nuclear form (PubMed:22732093). Also involved in transcriptional activation of cytokines and chemokines independent of the inflammasome; this function may involve AP-1, NF-kappa-B, MAPK and caspase-8 signaling pathways (PubMed:12486103, PubMed:16585594). For regulation of NF-kappa-B activating and inhibiting functions have been reported (PubMed:12486103). Modulates NF-kappa-B induction at the level of the IKK complex by inhibiting kinase activity of CHUK and IKBK (PubMed:12486103, PubMed:16585594). Proposed to compete with RIPK2 for association with CASP1 thereby down-regulating CASP1-mediated RIPK2-dependent NF-kappa-B activation and activating interleukin-1 beta processing (PubMed:16585594). Modulates host resistance to DNA virus infection, probably by inducing the cleavage of and inactivating CGAS in presence of cytoplasmic double-stranded DNA (PubMed:28314590)\nMay have a regulating effect on the function as inflammasome adapter\nSeems to inhibit inflammasome-mediated maturation of interleukin-1 beta","subunit":"Self-associates; enforced oligomerization induces apoptosis, NF-kappa-B regulation and interleukin-1 beta secretion (PubMed:15641782, PubMed:17599095, PubMed:33420028, PubMed:33420033, PubMed:34706239). Homooligomers can form disk-like particles of approximately 12 nm diameter and approximately 1 nm height (PubMed:15641782, PubMed:17599095). Next to isoform 1, also isoform 2 and isoform 3 may be involved in oligomerization leading to functional regulation (Probable). Component of several inflammasomes containing one pattern recognition receptor/sensor, such as NLRP1, NLRP2, NLRP3, NLRP6, NLRC4, AIM2, MEFV or NOD2, and probably NLRC4, NLRP12 or IFI16 (PubMed:11374873, PubMed:12191486, PubMed:15030775, PubMed:15456791, PubMed:19158676, PubMed:23530044, PubMed:27432880, PubMed:29440442, PubMed:30674671, PubMed:33980849, PubMed:34678144, PubMed:35559676). Major component of the ASC pyroptosome, a 1-2 um supramolecular assembly (one per macrophage cell) which consists of oligomerized PYCARD dimers and CASP1 (PubMed:17599095). Interacts with CASP1 (precursor form); the interaction induces activation of CASP1 leading to the processing of interleukin-1 beta; PYCARD competes with RIPK2 for binding to CASP1 (PubMed:11967258, PubMed:14634131, PubMed:16585594, PubMed:17599095, PubMed:33420033). Interacts with NLRP3; the interaction requires the homooligomerization of NLRP3 (PubMed:11786556, PubMed:15020601, PubMed:15030775, PubMed:34341353, PubMed:35559676). Interacts with NLRP2, NLRC4, MEFV, CARD16, AIM2, IFI16, NOD2, RIGI, RIPK2, PYDC1, PYDC2, NLRP10, CASP8, CHUK, IKBKB and BAX (PubMed:11374873, PubMed:11498534, PubMed:12486103, PubMed:12646168, PubMed:12656673, PubMed:14730312, PubMed:15096476, PubMed:15456791, PubMed:17178784, PubMed:17339483, PubMed:18362139, PubMed:19158675, PubMed:19158676, PubMed:19915568, PubMed:21575908, PubMed:23530044, PubMed:29440442, PubMed:33980849). Component of the AIM2 PANoptosome complex, a multiprotein complex that drives inflammatory cell death (PANoptosis) (By similarity). Interacts with FAM120A; this interaction inhibits inflammasome activation (PubMed:40250624)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11103777","12486103","12646168","14499617","14730312","15030775","16585594","16964285","16982856","17349957","17599095","19158675","19158676","19234215","19494289","19759850","19915568","20482797","21487011","22732093","23530044","24630722","25847972","28314590","29440442","30674671","33980849","34678144","34706239","36050480"],"location":"Cytoplasm；Inflammasome；Endoplasmic reticulum；Mitochondrion；Nucleus；Golgi apparatus membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Functions as a key mediator in apoptosis and inflammation (PubMed:11103777, PubMed:12646168, PubMed:15030775, PubMed:17349957, PubMed:17599095, PubMed:19158675, PubMed:19158676, PubMed:19234215, PubMed:19494289, PubMed:21487011, PubMed:24630722, PubMed:25847972, PubMed:30674671, PubMed:34678144, PubMed:36050480).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢"},"PYGO1":{"hgnc":"HGNC:30256","symbol":"PYGO1","accessions":["Q9Y3Y4"],"name":"Pygopus homolog 1","length":"419","function":"Involved in signal transduction through the Wnt pathway","subunit":"Interacts with BCL9 via The PHD-type zinc finger motiv, and thereby becomes part of the nuclear beta-catenin/TCF complex. Identified in a complex with BCL9L, CDC73, CTNNB1 and PYGO1. Interacts with histone H3 mono-, di- or tri-methylated at 'Lys4' (H3K4me1, H3K4me2, H3K4me3); the interaction is enhanced by the interaction with BCL9","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Involved in signal transduction through the Wnt pathway","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"PYHIN1":{"hgnc":"HGNC:28894","symbol":"PYHIN1","accessions":["Q6K0P9"],"name":"Pyrin and HIN domain-containing protein 1","length":"492","function":"Major mediator of the tumor suppressor activity of IFN in breast cancer cells. Promotes ubiquitination and subsequent degradation of MDM2, which leads to p53/TP53 stabilization. Promotes ubiquitination and subsequent degradation of HDAC1, which in turn enhances maspin expression, and impairs invasive activity of cancer cells","subunit":"Interacts with MDM2","family":"Belongs to the HIN-200 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16479015","18247378"],"location":"Nucleus, nucleoplasm；Nucleus；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Major mediator of the tumor suppressor activity of IFN in breast cancer cells.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"PYM1":{"hgnc":"HGNC:30258","symbol":"PYM1","accessions":["Q9BRP8"],"name":"Partner of Y14 and mago","length":"204","function":"Key regulator of the exon junction complex (EJC), a multiprotein complex that associates immediately upstream of the exon-exon junction on mRNAs and serves as a positional landmark for the intron exon structure of genes and directs post-transcriptional processes in the cytoplasm such as mRNA export, nonsense-mediated mRNA decay (NMD) or translation. Acts as an EJC disassembly factor, allowing translation-dependent EJC removal and recycling by disrupting mature EJC from spliced mRNAs. Its association with the 40S ribosomal subunit probably prevents a translation-independent disassembly of the EJC from spliced mRNAs, by restricting its activity to mRNAs that have been translated. Interferes with NMD and enhances translation of spliced mRNAs, probably by antagonizing EJC functions. May bind RNA; the relevance of RNA-binding remains unclear in vivo, RNA-binding was detected by PubMed:14968132, while PubMed:19410547 did not detect RNA-binding activity independently of the EJC","subunit":"Interacts (via N-terminus) with MAGOH and RBM8A; the interaction is direct. Associates (eIF2A-like region) with the 40S ribosomal subunit and the 48S preinitiation complex","family":"Belongs to the pym family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18026120","19410547"],"location":"Cytoplasm；Nucleus, nucleolus；Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；翻译/核糖体；注释原文：Key regulator of the exon junction complex (EJC), a multiprotein complex that associates immediately upstream of the exon-exon junction on mRNAs and serves as a positional landmark for the intron exon structure of genes and directs post-transcriptional processes in the cytoplasm such as mRNA export, nonsense-mediated mRNA decay (NMD) or translation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；翻译/核糖体"},"QKI":{"hgnc":"HGNC:21100","symbol":"QKI","accessions":["Q96PU8"],"name":"KH domain-containing RNA-binding protein QKI","length":"341","function":"RNA reader protein, which recognizes and binds specific RNAs, thereby regulating RNA metabolic processes, such as pre-mRNA splicing, circular RNA (circRNA) formation, mRNA export, mRNA stability and/or translation (PubMed:22398723, PubMed:23630077, PubMed:25768908, PubMed:27029405, PubMed:31331967, PubMed:37379838). Involved in various cellular processes, such as mRNA storage into stress granules, apoptosis, lipid deposition, interferon response, glial cell fate and development (PubMed:25768908, PubMed:31829086, PubMed:34428287, PubMed:37379838). Binds to the 5'-NACUAAY-N(1,20)-UAAY-3' RNA core sequence (PubMed:23630077). Acts as a mRNA modification reader that specifically recognizes and binds mRNA transcripts modified by internal N(7)-methylguanine (m7G) (PubMed:37379838). Promotes the formation of circular RNAs (circRNAs) during the epithelial to mesenchymal transition and in cardiomyocytes: acts by binding to sites flanking circRNA-forming exons (PubMed:25768908). CircRNAs are produced by back-splicing circularization of pre-mRNAs (PubMed:25768908). Plays a central role in myelinization via 3 distinct mechanisms (PubMed:16641098). First, acts by protecting and promoting stability of target mRNAs such as MBP, SIRT2 and CDKN1B, which promotes oligodendrocyte differentiation (By similarity). Second, participates in mRNA transport by regulating the nuclear export of MBP mRNA (By similarity). Finally, indirectly regulates mRNA splicing of MAG pre-mRNA during oligodendrocyte differentiation by acting as a negative regulator of MAG exon 12 alternative splicing: acts by binding to HNRNPA1 mRNA splicing factor, preventing its translation (By similarity). Involved in microglia differentiation and remyelination by regulating microexon alternative splicing of the Rho GTPase pathway (By similarity). Involved in macrophage differentiation: promotes monocyte differentiation by regulating pre-mRNA splicing in naive peripheral blood monocytes (PubMed:27029405). Acts as an important regulator of muscle development: required for the contractile function of cardiomyocytes by regulating alternative splicing of cardiomyocyte transcripts (By similarity). Acts as a negative regulator of thermogenesis by decreasing stability, nuclear export and translation of mRNAs encoding PPARGC1A and UCP1 (By similarity). Also required for visceral endoderm function and blood vessel development (By similarity). May also play a role in smooth muscle development (PubMed:31331967). In addition to its RNA-binding activity, also acts as a nuclear transcription coactivator for SREBF2/SREBP2 (By similarity)\nNuclear isoform that acts as an indirect regulator of mRNA splicing (By similarity). Regulates mRNA splicing of MAG pre-mRNA by inhibiting translation of HNRNPA1 mRNA, thereby preventing MAG exon 12 alternative splicing (By similarity). Involved in oligodendrocyte differentiation by promoting stabilization of SIRT2 mRNA (By similarity). Acts as a negative regulator of the interferon response by binding to MAVS mRNA, down-regulating its expression (PubMed:31829086). Also inhibits the interferon response by binding to fibrinectin FN1 pre-mRNA, repressing EDA exon inclusion in FN1 (PubMed:34428287). Delays macrophage differentiation by binding to CSF1R mRNA, promoting its degradation (PubMed:22398723). In addition to its RNA-binding activity, also acts as a nuclear transcription coactivator for SREBF2/SREBP2, promoting SREBF2/SREBP2-dependent cholesterol biosynthesis (By similarity). SREBF2/SREBP2-dependent cholesterol biosynthesis participates to myelinization and is required for eye lens transparency (By similarity)\nCytosolic isoform that specifically recognizes and binds mRNA transcripts modified by internal N(7)-methylguanine (m7G) (PubMed:37379838). Interaction with G3BP1 promotes localization of m7G-containing mRNAs into stress granules in response to stress, thereby suppressing their translation (PubMed:37379838). Acts as a translational repressor for HNRNPA1 and GLI1 (By similarity). Translation inhibition of HNRNPA1 during oligodendrocyte differentiation prevents inclusion of exon 12 in MAG pre-mRNA splicing (By similarity). Involved in astrocyte differentiation by regulating translation of target mRNAs (By similarity)\nCytosolic isoform that specifically recognizes and binds mRNA transcripts modified by internal N(7)-methylguanine (m7G) (PubMed:37379838). Interaction with G3BP1 promotes localization of m7G-containing mRNAs into stress granules in response to stress, thereby suppressing their translation (PubMed:37379838). Acts as a negative regulator of angiogenesis by binding to mRNAs encoding CDH5, NLGN1 and TNFAIP6, promoting their degradation (PubMed:32732889). Can also induce apoptosis in the cytoplasm (By similarity). Heterodimerization with other isoforms results in nuclear translocation of isoform QKI7 and suppression of apoptosis (By similarity). Also binds some microRNAs: promotes stabilitation of miR-122 by mediating recruitment of poly(A) RNA polymerase TENT2, leading to 3' adenylation and stabilization of miR-122 (PubMed:31792053)","subunit":"Homodimer; does not require RNA to homodimerize (PubMed:23630077). Able to heterodimerize with BICC1 (By similarity)\nInteracts with G3BP1; directing N(7)-methylguanine (m7G)-containing mRNAs to stress granules to suppress mRNA translation\nInteracts with G3BP1; directing N(7)-methylguanine (m7G)-containing mRNAs to stress granules to suppress mRNA translation (PubMed:37379838). Interacts with TENT2; promoting stabilization of miR-122 (PubMed:31792053)","family":"Belongs to the quaking family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16641098","22398723","23630077","25768908","27029405","31331967","31792053","31829086","32732889","34428287","37379838"],"location":"Nucleus；Cytoplasm；Cytoplasm, cytosol；Cytoplasm, Stress granule","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；核质运输；染色质/转录调控；翻译/核糖体；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：RNA reader protein, which recognizes and binds specific RNAs, thereby regulating RNA metabolic processes, such as pre-mRNA splicing, circular RNA (circRNA) formation, mRNA export, mRNA stability and/or translation (PubMed:22398723, PubMed:23630077, PubMed:25768908, PubMed:27029405, PubMed:31331967, PubMed:37379838).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；核质运输；染色质/转录调控；翻译/核糖体；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"QRICH1":{"hgnc":"HGNC:24713","symbol":"QRICH1","accessions":["Q2TAL8"],"name":"Transcriptional regulator QRICH1","length":"776","function":"Transcriptional regulator that acts as a mediator of the integrated stress response (ISR) through transcriptional control of protein homeostasis under conditions of ER stress (PubMed:33384352, PubMed:40355839). Controls the outcome of the unfolded protein response (UPR) which is an ER-stress response pathway (PubMed:33384352). ER stress induces QRICH1 translation by a ribosome translation re-initiation mechanism in response to EIF2S1/eIF-2-alpha phosphorylation, and stress-induced QRICH1 regulates a transcriptional program associated with protein translation, protein secretion-mediated proteotoxicity and cell death during the terminal UPR (PubMed:33384352). May cooperate with ATF4 transcription factor signaling to regulate ER homeostasis which is critical for cell viability (PubMed:33384352). Up-regulates CASP3/caspase-3 activity in epithelial cells under ER stress. Central regulator of proteotoxicity associated with ER stress-mediated inflammatory diseases in the intestines and liver (PubMed:33384352). Core component of the zincore complex, a heterotetramer that acts as a molecular 'grip' to stabilize transcription factors at DNA-binding sites across the genome, thereby controlling gene expression (PubMed:40608935). The zincore complex binds specifically to zinc finger transcription factors, such as ZFP91, ZNF652, ZNF526 and PRDM15, and stabilizes them onto their cognate DNA motif (PubMed:40608935). Involved in chondrocyte hypertrophy, a process required for normal longitudinal bone growth (PubMed:30281152)","subunit":"Component of the zincore complex, a heterotetramer composed of a dimer of QRICH1 and SEPHS1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["30281152","33384352","40355839","40608935"],"location":"Nucleus；Chromosome；Cytoplasm；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；注释原文：Transcriptional regulator that acts as a mediator of the integrated stress response (ISR) through transcriptional control of protein homeostasis under conditions of ER stress (PubMed:33384352, PubMed:40355839).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡"},"QSOX2":{"hgnc":"HGNC:30249","symbol":"QSOX2","accessions":["Q6ZRP7"],"name":"Sulfhydryl oxidase 2","length":"698","function":"Sulfhydryl oxidase that catalyzes the oxidation of protein thiol groups to form disulfide bonds, with the reduction of oxygen to hydrogen peroxide (By similarity). May contribute to disulfide bond formation in secreted proteins (By similarity). May play a role in regulating the sensitization of neuroblastoma cells for interferon-gamma-induced apoptosis (PubMed:14633699). Required for normal ovarian function (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the quiescin-sulfhydryl oxidase (QSOX) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14633699"],"location":"Membrane；Single-pass membrane protein；Secreted；Cell membrane；Nucleus membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"免疫/炎症/细胞死亡；注释原文：Sulfhydryl oxidase that catalyzes the oxidation of protein thiol groups to form disulfide bonds, with the reduction of oxygen to hydrogen peroxide (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"免疫/炎症/细胞死亡"},"R3HCC1":{"hgnc":"HGNC:27329","symbol":"R3HCC1","accessions":["Q9Y3T6"],"name":"R3H and coiled-coil domain-containing protein 1","length":"440","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 16-81: R3H [ECO:0000255/PROSITE-ProRule/PRU00382]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"R3HCC1L":{"hgnc":"HGNC:23512","symbol":"R3HCC1L","accessions":["Q7Z5L2"],"name":"Coiled-coil domain-containing protein R3HCC1L","length":"792","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"May interact with the exon junction complex (EJC) composed at least of CASC3, EIF4A3, MAGOH and RBM8A","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"R3HDM1":{"hgnc":"HGNC:9757","symbol":"R3HDM1","accessions":["Q15032"],"name":"R3H domain-containing protein 1","length":"1099","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 168-231: R3H [ECO:0000255/PROSITE-ProRule/PRU00382]\nDomain 232-302: SUZ [ECO:0000255/PROSITE-ProRule/PRU01009]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"R3HDM2":{"hgnc":"HGNC:29167","symbol":"R3HDM2","accessions":["Q9Y2K5"],"name":"R3H domain-containing protein 2","length":"976","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 169-232: R3H [ECO:0000255/PROSITE-ProRule/PRU00382]\nDomain 233-310: SUZ [ECO:0000255/PROSITE-ProRule/PRU01009]","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"R3HDM4":{"hgnc":"HGNC:28270","symbol":"R3HDM4","accessions":["Q96D70"],"name":"R3H domain-containing protein 4","length":"268","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 187-250: R3H [ECO:0000255/PROSITE-ProRule/PRU00382]","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"RAB11FIP2":{"hgnc":"HGNC:29152","symbol":"RAB11FIP2","accessions":["Q7L804"],"name":"Rab11 family-interacting protein 2","length":"512","function":"A Rab11 effector binding preferentially phosphatidylinositol 3,4,5-trisphosphate (PtdInsP3) and phosphatidic acid (PA) and acting in the regulation of the transport of vesicles from the endosomal recycling compartment (ERC) to the plasma membrane. Involved in insulin granule exocytosis. Also involved in receptor-mediated endocytosis and membrane trafficking of recycling endosomes, probably originating from clathrin-coated vesicles. Required in a complex with MYO5B and RAB11 for the transport of NPC1L1 to the plasma membrane. Also acts as a regulator of cell polarity. Plays an essential role in phagocytosis through a mechanism involving TICAM2, RAC1 and CDC42 Rho GTPases for controlling actin-dynamics","subunit":"Homooligomerizes in a Rab11-independent manner. Forms a heterooligomeric complex with RAB11FIP4. Interacts with AP2A1, MYO5B, RAB25 and REPS1. Interacts with RAB11A and RAB11B (activated GTP-bound form). Interacts with NPC1L1. Interacts (via NPF motifs) with EHD1 and EHD3. Interacts with TICAM2; this interaction directs RAB11FIP2 to the phagosome (PubMed:30883606). Interacts with RAB14 and RAB25 (GTP-bound forms) (PubMed:26032412)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12364336","15304524","16251358","16775013","19542231","30883606"],"location":"Cell projection, phagocytic cup；Cell membrane；Peripheral membrane protein；Recycling endosome membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：A Rab11 effector binding preferentially phosphatidylinositol 3,4,5-trisphosphate (PtdInsP3) and phosphatidic acid (PA) and acting in the regulation of the transport of vesicles from the endosomal recycling compartment (ERC) to the plasma membrane.","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面"},"RAB3A":{"hgnc":"HGNC:9777","symbol":"RAB3A","accessions":["P20336"],"name":"Ras-related protein Rab-3A","length":"220","function":"The small GTPases Rab are key regulators of intracellular membrane trafficking, from the formation of transport vesicles to their fusion with membranes (PubMed:2501306). Rabs cycle between an inactive GDP-bound form and an active GTP-bound form that is able to recruit to membranes different sets of downstream effectors directly responsible for vesicle formation, movement, tethering and fusion (PubMed:2501306). RAB3A plays a central role in regulated exocytosis and secretion. Controls the recruitment, tethering and docking of secretory vesicles to the plasma membrane (PubMed:2501306). Upon stimulation, switches to its active GTP-bound form, cycles to vesicles and recruits effectors such as RIMS1, RIMS2, Rabphilin-3A/RPH3A, RPH3AL or SYTL4 to help the docking of vesicules onto the plasma membrane (By similarity). Upon GTP hydrolysis by GTPase-activating protein, dissociates from the vesicle membrane allowing the exocytosis to proceed (By similarity). Stimulates insulin secretion through interaction with RIMS2 or RPH3AL effectors in pancreatic beta cells (By similarity). Regulates calcium-dependent lysosome exocytosis and plasma membrane repair (PMR) via the interaction with 2 effectors, SYTL4 and myosin-9/MYH9 (PubMed:27325790). Acts as a positive regulator of acrosome content secretion in sperm cells by interacting with RIMS1 (PubMed:22248876, PubMed:30599141). Also plays a role in the regulation of dopamine release by interacting with synaptotagmin I/SYT (By similarity)","subunit":"Interacts with RIMS1 (PubMed:41492970). Interacts with RIMS2 (By similarity). Interacts with Rabphilin-3A/RPH3A (PubMed:40166812, PubMed:41492970). Interacts with Rab effector Noc2/RPH3AL (By similarity). Interacts with SYTL4 (By similarity). Interacts with RAB3IP (By similarity). Interacts with SGSM1 and SGSM3 (By similarity). Interacts with SYT1 (By similarity). Interacts with MYH9; this interaction is essential for lysosome exocytosis and plasma membrane repair (PubMed:27325790). Interacts with STXBP1; this interaction promotes RAB3A dissociation from the vesicle membrane (By similarity). Interacts with SNCA (PubMed:15207266). The GTP-bound form interacts with REP15 (PubMed:35871249). Interacts with GDI1, GDI2, CHM and CHML; phosphorylation at Thr-86 disrupts these interactions (PubMed:29125462). Interacts with MADD (via uDENN domain); the GTP-bound form is preferred for interaction (By similarity)","family":"Belongs to the small GTPase superfamily. Rab family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22248876","2501306","27325790","30599141"],"location":"Cytoplasm, cytosol；Lysosome；Cytoplasmic vesicle, secretory vesicle；Cell projection, axon；Cell membrane；Lipid-anchor；Cytoplasmic side；Presynapse；Postsynapse","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；注释原文：The small GTPases Rab are key regulators of intracellular membrane trafficking, from the formation of transport vesicles to their fusion with membranes (PubMed:2501306).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"膜运输/高尔基/内吞"},"RAB3GAP1":{"hgnc":"HGNC:17063","symbol":"RAB3GAP1","accessions":["Q15042"],"name":"Rab3 GTPase-activating protein catalytic subunit","length":"981","function":"Catalytic subunit of the Rab3 GTPase-activating (Rab3GAP) complex composed of RAB3GAP1 and RAB3GAP2, which accelerates the otherwise slow GTP hydrolysis catalyzed by Rab proteins (PubMed:9030515, PubMed:10859313, PubMed:39779760). Has GTPase-activating protein (GAP) activity towards various Rab3 subfamily members (RAB3A, RAB3B, RAB3C and RAB3D), RAB5A and RAB43 (PubMed:10859313, PubMed:9030515, PubMed:39779760). Additionally, it has guanine nucleotide exchange factor (GEF) activity towards RAB18, promoting GDP release from RAB18 and the conversion of inactive RAB18-GDP to the active form RAB18-GTP (PubMed:24891604, PubMed:39779760). Recruits and stabilizes RAB18 at the cis-Golgi membrane in fibroblasts where RAB18 is most likely activated (PubMed:26063829). Also involved in RAB18 recruitment at the endoplasmic reticulum (ER) membrane where it maintains proper ER structure (PubMed:24891604). Required for normal eye and brain development (PubMed:15696165, PubMed:23420520). May participate in neurodevelopmental processes such as cell proliferation, migration and differentiation before synapse formation, and is involved in regulating non-synaptic vesicular release of neurotransmitters (PubMed:9030515, PubMed:9852129)","subunit":"The Rab3 GTPase-activating complex is a heterodimer composed of RAB3GAP1 and RAB3GAP2 (By similarity). The Rab3 GTPase-activating complex interacts with DMXL2 (By similarity). Interacts with LMAN1 (PubMed:22337587)","family":"Belongs to the Rab3-GAP catalytic subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10859313","15696165","23420520","24891604","26063829","39779760","9030515","9852129"],"location":"Cytoplasm；Endoplasmic reticulum；Golgi apparatus, cis-Golgi network","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；黏附/受体/细胞表面；发育/分化；注释原文：Catalytic subunit of the Rab3 GTPase-activating (Rab3GAP) complex composed of RAB3GAP1 and RAB3GAP2, which accelerates the otherwise slow GTP hydrolysis catalyzed by Rab proteins (PubMed:9030515, PubMed:10859313, PubMed:39779760).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；黏附/受体/细胞表面；发育/分化"},"RAB3IP":{"hgnc":"HGNC:16508","symbol":"RAB3IP","accessions":["Q96QF0"],"name":"Rab-3A-interacting protein","length":"476","function":"Guanine nucleotide exchange factor (GEF) which may activate RAB8A and RAB8B (PubMed:12221131, PubMed:26824392). Promotes the exchange of GDP to GTP, converting inactive GDP-bound Rab proteins into their active GTP-bound form (PubMed:12221131, PubMed:26824392). Mediates the release of GDP from RAB8A and RAB8B but not from RAB3A or RAB5 (PubMed:20937701, PubMed:26824392). Modulates actin organization and promotes polarized transport of RAB8A-specific vesicles to the cell surface (PubMed:12221131). Together with RAB11A, RAB8A, the exocyst complex, PARD3, PRKCI, ANXA2, CDC42 and DNMBP promotes transcytosis of PODXL to the apical membrane initiation sites (AMIS), apical surface formation and lumenogenesis (PubMed:20890297). Part of the ciliary targeting complex containing Rab11, ASAP1, RAB3IP and RAB11FIP3 and ARF4 that promotes RAB3IP preciliary vesicle trafficking to mother centriole and ciliogenesis initiation (PubMed:25673879, PubMed:31204173)","subunit":"Homodimer (PubMed:26258637). Interacts with the N-terminal region of SSX2 (PubMed:12007189). Interacts with the GDP-bound forms of RAB8A and RAB8B (PubMed:12221131, PubMed:26824392). The interaction with RAB8A is prevented by phosphorylation of RAB8A at 'Thr-72' (PubMed:26824392). Interacts with the GDP-bound forms of RAB3A and RAB3D (PubMed:12221131). Interacts with DCDC1 (PubMed:12007189, PubMed:12221131, PubMed:22159412, PubMed:26824392). Interacts (via the N-terminal region) with TRAPPC14; this interaction mediates RAB3IP association with the TRAPP II complex (PubMed:31467083). Forms a heterotetramer with RAB11A where RAB3IP homodimer binds two RAB11A subunits (PubMed:26258637). Forms a complex with RAB11A and RAB11FIP3, probably a heterohexamer with two of each protein subunit, where Rabin8/RAB3IP and RAB11FIP3 simultaneously bind to RAB11A; the complex promotes preciliary trafficking (PubMed:26258637, PubMed:31204173). Forms a complex containing RAB11A, ASAP1, RAB3IP, RAP11FIP3 and ARF4; the complex promotes preciliary trafficking; the complex binds to RHO in photoreceptor cells and promotes RHO ciliary transport (PubMed:25673879)","family":"Belongs to the SEC2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12221131","20890297","20937701","25673879","26824392","31204173"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton；Cell projection, lamellipodium；Vesicle；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；注释原文：Guanine nucleotide exchange factor (GEF) which may activate RAB8A and RAB8B (PubMed:12221131, PubMed:26824392).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛"},"RAB9A":{"hgnc":"HGNC:9792","symbol":"RAB9A","accessions":["P51151"],"name":"Ras-related protein Rab-9A","length":"201","function":"The small GTPases Rab are key regulators of intracellular membrane trafficking, from the formation of transport vesicles to their fusion with membranes. Rabs cycle between an inactive GDP-bound form and an active GTP-bound form that is able to recruit to membranes different sets of downstream effectors directly responsible for vesicle formation, movement, tethering and fusion (By similarity). RAB9A is involved in the transport of proteins between the endosomes and the trans-Golgi network (TGN) (PubMed:34793709). Specifically uses NDE1/NDEL1 as an effector to interact with the dynein motor complex in order to control retrograde trafficking of RAB9-associated late endosomes to the TGN (PubMed:34793709). Involved in the recruitment of SGSM2 to melanosomes and is required for the proper trafficking of melanogenic enzymes TYR, TYRP1 and DCT/TYRP2 to melanosomes in melanocytes (By similarity)","subunit":"Interacts (preferentially in its GTP-bound form) with GCC2 (via its GRIP domain) (PubMed:16885419, PubMed:18243103). Interacts (GTP-bound form) with SGSM1; the GDP-bound form has much lower affinity for SGSM1 (PubMed:22637480). Interacts with SGSM2 (PubMed:21808068). The GTP-bound form but not the GDP-bound form interacts with HPS4 and BLOC-3 complex (heterodimer of HPS1 and HPS4) but does not interact with HPS1 alone (PubMed:20048159). Interacts (GTP-bound form) with NDE1; two RAB9A-GTP molecules lie on the opposite sides of the NDE1 homodimer; the interaction leads to RAB9A-dynein motor tethering (PubMed:34793709). Interacts (GTP-bound form) with NDEL1 (PubMed:34793709)","family":"Belongs to the small GTPase superfamily. Rab family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["34793709"],"location":"Cell membrane；Lipid-anchor；Cytoplasmic side；Endoplasmic reticulum membrane；Golgi apparatus membrane；Late endosome；Cytoplasmic vesicle, phagosome membrane；Cytoplasmic vesicle, phagosome；Cytoplasmic vesicle membrane；Melanosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；注释原文：The small GTPases Rab are key regulators of intracellular membrane trafficking, from the formation of transport vesicles to their fusion with membranes.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛"},"RABGEF1":{"hgnc":"HGNC:17676","symbol":"RABGEF1","accessions":["Q9UJ41"],"name":"Rab5 GDP/GTP exchange factor","length":"491","function":"Acts as a guanine-nucleotide releasing factor (GEF) for RAB5A by promoting the conversion of inactive RAB-GDP to the active form RAB-GTP (PubMed:15339665, PubMed:9323142). Forms a complex with RABEP1 that acts as Rab4/Rab5 effector regulating endosome fusion. Involved in endocytic membrane fusion and membrane trafficking of recycling endosomes (PubMed:11452015, PubMed:9323142). Also functions as a ubiquitin ligase (By similarity)","subunit":"Interacts with RGS14; the interaction is GTP-dependent (By similarity). Heterodimer with RABEP1. The heterodimer binds RAB4A and RAB5A that have been activated by GTP-binding. Interacts with RAB21, and with 100-fold lower affinity also with RAB22. Binds TSC2, GGA1, GGA2, GGA3, AP1G1 and AP1G2. Interacts with ubiquitinated EGFR","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11452015","15339665","9323142"],"location":"Cytoplasm；Early endosome；Recycling endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；膜运输/高尔基/内吞；注释原文：Acts as a guanine-nucleotide releasing factor (GEF) for RAB5A by promoting the conversion of inactive RAB-GDP to the active form RAB-GTP (PubMed:15339665, PubMed:9323142).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；膜运输/高尔基/内吞"},"RABL6":{"hgnc":"HGNC:24703","symbol":"RABL6","accessions":["Q3YEC7"],"name":"Rab-like protein 6","length":"729","function":"Small GTPase involved in the regulation of cell growth and survival (PubMed:19433581). Promotes cellular proliferation (PubMed:16582619, PubMed:19433581). May reduce growth inhibitory activity of CDKN2A (PubMed:16582619)","subunit":"","family":"Belongs to the small GTPase superfamily. Rab family","domains":[],"function_pmids":["16582619","19433581"],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Small GTPase involved in the regulation of cell growth and survival (PubMed:19433581). Promotes cellular proliferation (PubMed:16582619, PubMed:19433581). May reduce growth inhibitory activity of CDKN2A (PubMed:16582619)"},"RAC1":{"hgnc":"HGNC:9801","symbol":"RAC1","accessions":["P63000"],"name":"Ras-related C3 botulinum toxin substrate 1","length":"192","function":"Plasma membrane-associated small GTPase which cycles between active GTP-bound and inactive GDP-bound states. In its active state, binds to a variety of effector proteins to regulate cellular responses such as secretory processes, phagocytosis of apoptotic cells, epithelial cell polarization, neurons adhesion, migration and differentiation, and growth-factor induced formation of membrane ruffles (PubMed:1643658, PubMed:22843693, PubMed:23512198, PubMed:28886345). Rac1 p21/rho GDI heterodimer is the active component of the cytosolic factor sigma 1, which is involved in stimulation of the NADPH oxidase activity in macrophages. Essential for the SPATA13-mediated regulation of cell migration and adhesion assembly and disassembly. Stimulates PKN2 kinase activity (PubMed:9121475). In concert with RAB7A, plays a role in regulating the formation of RBs (ruffled borders) in osteoclasts (PubMed:1643658). In podocytes, promotes nuclear shuttling of NR3C2; this modulation is required for a proper kidney functioning. Required for atypical chemokine receptor ACKR2-induced LIMK1-PAK1-dependent phosphorylation of cofilin (CFL1) and for up-regulation of ACKR2 from endosomal compartment to cell membrane, increasing its efficiency in chemokine uptake and degradation. In neurons, is involved in dendritic spine formation and synaptic plasticity (By similarity). In hippocampal neurons, involved in spine morphogenesis and synapse formation, through local activation at synapses by guanine nucleotide exchange factors (GEFs), such as ARHGEF6/ARHGEF7/PIX (PubMed:12695502). In synapses, seems to mediate the regulation of F-actin cluster formation performed by SHANK3. In neurons, plays a crucial role in regulating GABA(A) receptor synaptic stability and hence GABAergic inhibitory synaptic transmission through its role in PAK1 activation and eventually F-actin stabilization (By similarity). Required for DSG3 translocation to cell-cell junctions, DSG3-mediated organization of cortical F-actin bundles and anchoring of actin at cell junctions; via interaction with DSG3 (PubMed:22796473). Subunit of the phagocyte NADPH oxidase complex that mediates the transfer of electrons from cytosolic NADPH to O2 to produce the superoxide anion (O2(-)) (PubMed:38355798)\nIsoform B has an accelerated GEF-independent GDP/GTP exchange and an impaired GTP hydrolysis, which is restored partially by GTPase-activating proteins (PubMed:14625275). It is able to bind to the GTPase-binding domain of PAK but not full-length PAK in a GTP-dependent manner, suggesting that the insertion does not completely abolish effector interaction (PubMed:14625275)","subunit":"Interacts with NISCH. Interacts with PIP5K1A. Interacts with the GTP-bound form of RAB7A. Interacts with SRGAP2. Interacts with CYFIP1/SRA-1. Interacts with PLXNB3. Interacts with ARHGDIA; the interaction is induced by SEMA5A, mediated through PLXNB3 and inactivates and stabilizes RAC1. Interacts (GTP-bound form preferentially) with PKN2 (via the REM repeats); the interaction stimulates autophosphorylation and phosphorylation of PKN2. Interacts with the GEF proteins PREX1, RASGRF2, FARP1, FARP2, DOCK1, DOCK2 and DOCK7, which promote the exchange between GDP and GTP, and therefore activate it (PubMed:32651375). Interacts with PARD6A, PARD6B and PARD6G in a GTP-dependent manner. Part of a quaternary complex containing PARD3, some PARD6 protein (PARD6A, PARD6B or PARD6G) and some atypical PKC protein (PRKCI or PRKCZ), which plays a central role in epithelial cell polarization. Found in a trimeric complex composed of DOCK1 and ELMO1, which plays a central role in phagocytosis of apoptotic cells. Interacts with RALBP1 via its effector domain. Interacts with PLXNB1. Part of a complex with MAP2K3, MAP3K3, CCM2 and DEF6. Interacts with BAIAP2, BAIAP2L1 and DEF6. Interacts with Y.pseudotuberculosis YPKA and PLCB2. Interacts with NOXA1. Interacts with ARHGEF2. Interacts with TBC1D2. Interacts with UNKL. Interacts with USP6. Interacts with SPATA13. Interacts with ARHGEF16; mediates activation of RAC1 by EPHA2. Interacts with ITGB4. Interacts with S100A8 and calprotectin (S100A8/9). Interacts with PACSIN2. Interacts with ITGB1BP1. Interacts (when active) with PPP5C (via TPR repeats); activates PPP5C phosphatase activity and translocates PPP5C to the cell membrane. Interacts with RAPH1 (via Ras associating and PH domains) (PubMed:18499456). Interacts with MTSS2 (via IMD domain); this interaction may be important to potentiate PDGF-induced RAC1 activation (PubMed:20875796). Interacts with PAK2 (PubMed:20696164). Interacts (GTP-bound form) with SH3RF1 and SH3RF3 (PubMed:20696164). Found in a complex with SH3RF1, MAPK8IP1/JIP1, MAP3K11/MLK3, MAP2K7/MKK7 and MAPK8/JNK1. Interacts (both active GTP- or inactive GDP-bound forms) with SH3RF2 (By similarity). Interacts (GTP-bound form preferentially) with CYRIB (PubMed:30250061, PubMed:31285585). Interacts with DOCK4 (via DOCKER domain); functions as a guanine nucleotide exchange factor (GEF) for RAC1 (PubMed:16464467). Interacts with GARRE1 (PubMed:31871319). Interacts with RAP1GDS1 (PubMed:12551911, PubMed:20709748). Interacts with TNFAIP8L2 (PubMed:32460619). May interact with ARHGAP36 (PubMed:35986704). Interacts with CD151 and integrin beta1/ITGB1 (PubMed:22843693). Interacts with DSG3; the interaction is required for DSG3 translocation to cell-cell junctions, organization of cortical F-actin bundles and actin anchoring at cell-cell junctions (PubMed:22796473). Component of the phagocyte NADPH oxidase complex composed of an obligatory core heterodimer formed by the membrane proteins CYBA and CYBB and the cytosolic regulatory subunits NCF1/p47-phox, NCF2/p67-phox, NCF4/p40-phox and the small GTPase RAC1 or RAC2 (PubMed:38355798). Interacts with NCF2 (PubMed:11090627). Interacts with ELMO1; the interaction is direct and promotes binding of DOCK2 to RAC1 (PubMed:32651375). Interacts with SYNJ2; this interaction is GTP-dependent and mediates the translocation of SYNJ2 from the cytoplasm to the plasma membrane (PubMed:11084340)","family":"Belongs to the small GTPase superfamily. Rho family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12695502","14625275","1643658","22796473","22843693","23512198","28886345","38355798","9121475"],"location":"Cell membrane；Lipid-anchor；Cytoplasmic side；Melanosome；Cytoplasm；Cell projection, lamellipodium；Cell projection, dendrite；Synapse；Nucleus；Cell projection, ruffle membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化；注释原文：Plasma membrane-associated small GTPase which cycles between active GTP-bound and inactive GDP-bound states.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化"},"RACGAP1":{"hgnc":"HGNC:9804","symbol":"RACGAP1","accessions":["Q9H0H5"],"name":"Rac GTPase-activating protein 1","length":"632","function":"Component of the centralspindlin complex that serves as a microtubule-dependent and Rho-mediated signaling required for the myosin contractile ring formation during the cell cycle cytokinesis. Required for proper attachment of the midbody to the cell membrane during cytokinesis. Sequentially binds to ECT2 and RAB11FIP3 which regulates cleavage furrow ingression and abscission during cytokinesis (PubMed:18511905). Plays key roles in controlling cell growth and differentiation of hematopoietic cells through mechanisms other than regulating Rac GTPase activity (PubMed:10979956). Has a critical role in erythropoiesis (PubMed:34818416). Also involved in the regulation of growth-related processes in adipocytes and myoblasts. May be involved in regulating spermatogenesis and in the RACGAP1 pathway in neuronal proliferation. Shows strong GAP (GTPase activation) activity towards CDC42 and RAC1 and less towards RHOA. Essential for the early stages of embryogenesis. May play a role in regulating cortical activity through RHOA during cytokinesis. May participate in the regulation of sulfate transport in male germ cells","subunit":"Heterotetramer of two molecules each of RACGAP1 and KIF23. Found in the centralspindlin complex. Associates with alpha-, beta- and gamma-tubulin and microtubules. Interacts via its Rho-GAP domain with RND2. Associates with AURKB during M phase. Interacts via its Rho-GAP domain and basic region with PRC1. The interaction with PRC1 inhibits its GAP activity towards CDC42 in vitro, which may be required for maintaining normal spindle morphology. Interacts with SLC26A8 via its N-terminus. Interacts with ECT2; the interaction is direct, occurs at anaphase and during cytokinesis in a microtubule-dependent manner, is enhanced by phosphorylation by PLK1 and phosphorylation at Ser-164 plays a major role in mediating binding (PubMed:25068414). Interacts with RAB11FIP3; the interaction occurs at late telophase (PubMed:18511905). Interacts with KIF23; the interaction is direct (PubMed:11782313, PubMed:16236794, PubMed:23235882). Interacts with ANKLE1 (PubMed:41361016)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10979956","11085985","11278976","11782313","14729465","15642749","16103226","16129829","16236794","18511905","19468300","19468302","23235882","9497316"],"location":"Nucleus；Cytoplasm；Cytoplasm, cytoskeleton, spindle；Cytoplasmic vesicle, secretory vesicle, acrosome；Cleavage furrow；Midbody, Midbody ring；Cell membrane；Peripheral membrane protein；Cytoplasmic side；Midbody","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；细胞骨架/纤毛；发育/分化；注释原文：Component of the centralspindlin complex that serves as a microtubule-dependent and Rho-mediated signaling required for the myosin contractile ring formation during the cell cycle cytokinesis.","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞周期/分裂；细胞骨架/纤毛；发育/分化"},"RACK1":{"hgnc":"HGNC:4399","symbol":"RACK1","accessions":["P63244"],"name":"Small ribosomal subunit protein RACK1","length":"317","function":"Scaffolding protein involved in the recruitment, assembly and/or regulation of a variety of signaling molecules. Interacts with a wide variety of proteins and plays a role in many cellular processes. Component of the 40S ribosomal subunit involved in translational repression (PubMed:23636399). Involved in the initiation of the ribosome quality control (RQC), a pathway that takes place when a ribosome has stalled during translation, by promoting ubiquitination of a subset of 40S ribosomal subunits (PubMed:28132843). Binds to and stabilizes activated protein kinase C (PKC), increasing PKC-mediated phosphorylation. May recruit activated PKC to the ribosome, leading to phosphorylation of EIF6. Inhibits the activity of SRC kinases including SRC, LCK and YES1. Inhibits cell growth by prolonging the G0/G1 phase of the cell cycle. Enhances phosphorylation of BMAL1 by PRKCA and inhibits transcriptional activity of the BMAL1-CLOCK heterodimer. Facilitates ligand-independent nuclear translocation of AR following PKC activation, represses AR transactivation activity and is required for phosphorylation of AR by SRC. Modulates IGF1R-dependent integrin signaling and promotes cell spreading and contact with the extracellular matrix. Involved in PKC-dependent translocation of ADAM12 to the cell membrane. Promotes the ubiquitination and proteasome-mediated degradation of proteins such as CLEC1B and HIF1A. Required for VANGL2 membrane localization, inhibits Wnt signaling, and regulates cellular polarization and oriented cell division during gastrulation. Required for PTK2/FAK1 phosphorylation and dephosphorylation. Regulates internalization of the muscarinic receptor CHRM2. Promotes apoptosis by increasing oligomerization of BAX and disrupting the interaction of BAX with the anti-apoptotic factor BCL2L. Inhibits TRPM6 channel activity. Regulates cell surface expression of some GPCRs such as TBXA2R. Plays a role in regulation of FLT1-mediated cell migration. Involved in the transport of ABCB4 from the Golgi to the apical bile canalicular membrane (PubMed:19674157). Promotes migration of breast carcinoma cells by binding to and activating RHOA (PubMed:20499158). Acts as an adapter for the dephosphorylation and inactivation of AKT1 by promoting recruitment of PP2A phosphatase to AKT1 (By similarity)\n(Microbial infection) Binds to Y.pseudotuberculosis yopK which leads to inhibition of phagocytosis and survival of bacteria following infection of host cells\n(Microbial infection) Enhances phosphorylation of HIV-1 Nef by PKCs\n(Microbial infection) In case of poxvirus infection, remodels the ribosomes so that they become optimal for the viral mRNAs (containing poly-A leaders) translation but not for host mRNAs\n(Microbial infection) Contributes to the cap-independent internal ribosome entry site (IRES)-mediated translation by some RNA viruses","subunit":"Monomer; also forms homodimers and homooligomers (PubMed:15140893, PubMed:20529362). Interacts with CPNE3 (PubMed:20010870). May interact with ABCB4 (PubMed:19674157). Component of the small (40S) ribosomal subunit (PubMed:23636399). Interacts with the 80S ribosome (PubMed:23636399). Binds NHERF1. Forms a ternary complex with TRIM63 and PRKCE. Interacts with HABP4, KRT1 and OTUB1. Interacts with SRC (via SH2 domain); the interaction is enhanced by tyrosine phosphorylation of RACK1. Recruited in a circadian manner into a nuclear complex which also includes BMAL1 and PRKCA. Interacts with AR. Interacts with IGF1R but not with INSR. Interacts with ADAM12. Interacts with CLEC1B (via N-terminal region) and with HIF1A; the interaction promotes their degradation. Interacts with RHOA; this enhances RHOA activation and promotes cell migration. Interacts with CHRM2; the interaction regulates CHRM2 internalization. Interacts with TRPM6 (via kinase domain). Interacts with PTK2/FAK1; required for PTK2/FAK1 phosphorylation and dephosphorylation. Interacts with FLT1. Interacts with TBXA2R isoform 2. Interacts with HRAS. Interacts with LARP4B. Interacts with LARP4 (PubMed:21098120). Interacts with PKD2L1. Interacts with isoform 2 of SLC4A7 (PubMed:29743600). Interacts with SLC9A5; this interaction regulates SLC9A5 cell-surface targeting and SLC9A5 activity (PubMed:24006492). Interacts with SLC9A6; this interaction regulates the distribution of SLC9A6 between endosomes and the plasma membrane (PubMed:18057008). Interacts with LACC1; this interaction may regulate macrophage autophagic flux\n(Microbial infection) Interacts with Y.pseudotuberculosis yopK\n(Microbial infection) Interacts with Y.pseudotuberculosis yopK. Interacts with a number of viral proteins including Epstein-Barr virus BZLF1 and HIV-1 Nef; interaction with Nef increases Nef phosphorylation by PKC\n(Microbial infection) Interacts with human respiratory syncytial virus matrix protein M; this interaction suppresses interferon signaling\n(Microbial infection) Interacts with Influenza protein PA-X\n(Microbial infection) Interacts with Toxoplasma gondii SAG1; the interaction promotes viability of host cells","family":"Belongs to the WD repeat G protein beta family. Ribosomal protein RACK1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11312657","11884618","12589061","12958311","17108144","17244529","17956333","18088317","18258429","18621736","19423701","19674157","19785988","20499158","20541605","20573744","20976005","21212275","21347310","23636399","25416947","28132843","28636603","9584165"],"location":"Cell membrane；Peripheral membrane protein；Cytoplasm；Cytoplasm, perinuclear region；Nucleus；Perikaryon；Cell projection, dendrite；Cell projection, phagocytic cup","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Scaffolding protein involved in the recruitment, assembly and/or regulation of a variety of signaling molecules.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"RAD18":{"hgnc":"HGNC:18278","symbol":"RAD18","accessions":["Q9NS91"],"name":"E3 ubiquitin-protein ligase RAD18","length":"495","function":"E3 ubiquitin-protein ligase involved in postreplication repair of UV-damaged DNA. Postreplication repair functions in gap-filling of a daughter strand on replication of damaged DNA. Associates to the E2 ubiquitin conjugating enzyme UBE2B to form the UBE2B-RAD18 ubiquitin ligase complex involved in mono-ubiquitination of DNA-associated PCNA on 'Lys-164'. Has ssDNA binding activity","subunit":"Homodimer (PubMed:21549715). Interacts with UBE2A and UBE2B, one homodimer binding one molecule of UBE2B. Interacts with SHPRH (PubMed:17108083, PubMed:17130289). Interacts with HLTF (PubMed:18316726, PubMed:18719106). Interacts with SPRTN; leading to enhance chromatin association of RAD18 and RAD18-mediated PCNA ubiquitination and translesion DNA synthesis (PubMed:22681887). Interacts (via C-terminus and phosphorylated form) with SLF1 (via BRCT domains); this interaction is required for efficient repair of UV-induced DNA damage (PubMed:15632077, PubMed:22036607, PubMed:25931565). Interacts with SLF2 (PubMed:25931565). Interacts with SMC5; this interaction is increased in a SLF1 or SLF2-dependent manner (PubMed:25931565). Interacts with DNA damage up-regulated protein DDUP (PubMed:35849344). Forms a complex with DDUP and H2AX following DDUP phosphorylation (PubMed:35849344)","family":"Belongs to the RAD18 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17108083","21659603"],"location":"Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：E3 ubiquitin-protein ligase involved in postreplication repair of UV-damaged DNA.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"RAD21":{"hgnc":"HGNC:9811","symbol":"RAD21","accessions":["O60216"],"name":"Double-strand-break repair protein rad21 homolog","length":"631","function":"As a member of the cohesin complex, involved in sister chromatid cohesion from the time of DNA replication in S phase to their segregation in mitosis, a function that is essential for proper chromosome segregation, post-replicative DNA repair, and the prevention of inappropriate recombination between repetitive regions (PubMed:11509732). The cohesin complex may also play a role in spindle pole assembly during mitosis (PubMed:11590136). In interphase, cohesins may function in the control of gene expression by binding to numerous sites within the genome (By similarity). May control RUNX1 gene expression (Probable). Binds to and represses APOB gene promoter (PubMed:25575569). May play a role in embryonic gut development, possibly through the regulation of enteric neuron development (By similarity)\nMay promote apoptosis","subunit":"Component of the cohesin complex, which consists of an SMC1A/B and SMC3 heterodimer core and 2 non-Smc subunits RAD21 and STAG1/SA1, STAG2/SA2 or STAG3/SA3 (PubMed:10931856, PubMed:11590136, PubMed:22628566, PubMed:25575569, PubMed:32409525). Interacts (via C-terminus) with SMC1A and (via N-terminus) with SMC3; these interactions are direct (PubMed:12198550, PubMed:32409525). The cohesin complex interacts with NUMA1 (PubMed:11590136). The cohesin complex also interacts with CDCA5, PDS5A and PDS5B; this interaction might regulate the ability of the cohesin complex to mediate sister chromatid cohesion (PubMed:15837422). The interaction with PDS5B is direct and is stimulated by STAG1/SA1 (PubMed:19696148). The cohesin complex interacts with the cohesin loading complex subunits NIPBL/Scc2 (via HEAT repeats) and MAU2/Scc4 (PubMed:22628566). NIPBL directly contacts all members of the complex, RAD21, SMC1A/B, SMC3 and STAG1 (PubMed:32409525). The cohesin complex interacts with DDX11/ChIR1 (PubMed:17105772). Directly interacts with WAPL; this interaction is stimulated by STAG1/SA1 (PubMed:19696148). Interacts with the ISWI chromatin remodeling complex component SMARCA5/SNF2h; the interaction is direct (PubMed:12198550). Interacts with the NuRD complex component CHD4; the interaction is direct (PubMed:12198550)","family":"Belongs to the rad21 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11509732","11590136","11875078","12417729","25575569"],"location":"Nucleus；Nucleus matrix；Chromosome；Chromosome, centromere；Cytoplasm, cytoskeleton, spindle pole；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡；发育/分化；注释原文：As a member of the cohesin complex, involved in sister chromatid cohesion from the time of DNA replication in S phase to their segregation in mitosis, a function that is essential for proper chromosome segregation, post-replicative DNA repair, and the prevention of inappropriate recombination between repetitive regions (PubMed:11509732).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡；发育/分化"},"RAD23A":{"hgnc":"HGNC:9812","symbol":"RAD23A","accessions":["P54725"],"name":"Lysine-specific demethylase RAD23A","length":"363","function":"Multifunctional protein that participates in histone H4K20 demethylation, DNA repair, ubiquitin-dependent protein degradation, transcriptional regulation, and viral replication (PubMed:12643283, PubMed:14621999, PubMed:15321727, PubMed:20614012, PubMed:32209475, PubMed:9372924). Specifically demethylates mono-, di- and trimethylated 'Lys-20' of histone H4 (H4K20me1, H4K20me2, H4K20me3, respectively) into unmethylated forms. Activates the transcription of coding genes by demethylating H4K20me1 and the transcription of repetitive elements by demethylating H4K20me3 (PubMed:32209475). Involved in modulation of proteasomal degradation. Binds to 'Lys-48'-linked polyubiquitin chains in a length-dependent manner and with a lower affinity to 'Lys-63'-linked polyubiquitin chains. Proposed to be capable to bind simultaneously to the 26S proteasome and to polyubiquitinated substrates and to deliver ubiquitinated proteins to the proteasome (PubMed:12643283, PubMed:14621999, PubMed:15321727). Involved in nucleotide excision repair, is considered functionally equivalent to RAD23B in global genome nucleotide excision repair (GG-NER) through its association with XPC. In vitro, the XPC-RAD23A complex demonstrates NER activity (PubMed:9372924). Can stabilize XPC (By similarity)\n(Microbial infection) Involved in -dependent replication of HIV-1 in non-proliferating cells and primary macrophages. Required for the association of HIV-1 Vpr with the host proteasome","subunit":"Interacts with XPC; the interaction suggests the existence of a functional equivalent variant XPC complex composed of XPC, RAD23A and CETN2 (PubMed:15322280, PubMed:9372924). RAD23A is expressed at a much higher level than RAD23B; consequently, most XPC complexes contain RAD23B (By similarity). Interacts with PSMD4 (PubMed:10488153, PubMed:12970176, PubMed:14557549). Interacts with ATXN3 (PubMed:10915768, PubMed:30455355). Interacts with UBQLN2 (PubMed:17098253)\n(Microbial infection) Interacts with HIV-1 Vpr","family":"Belongs to the RAD23 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12643283","14621999","15321727","20614012","32209475","9372924"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；注释原文：Multifunctional protein that participates in histone H4K20 demethylation, DNA repair, ubiquitin-dependent protein degradation, transcriptional regulation, and viral replication (PubMed:12643283, PubMed:14621999, PubMed:15321727, PubMed:20614012, PubMed:32209475, PubMed:9372924).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制"},"RAD23B":{"hgnc":"HGNC:9813","symbol":"RAD23B","accessions":["P54727"],"name":"Lysine-specific demethylase RAD23B","length":"409","function":"Multifunctional protein that participates in histone H4K20 demethylation, DNA repair, ubiquitin-dependent protein degradation and transcriptional regulation (PubMed:10488153, PubMed:32209475, PubMed:9372924). Specifically demethylates mono-, di- and trimethylated 'Lys-20' of histone H4 (H4K20me1, H4K20me2, H4K20me3, respectively) into unmethylated forms. Activates the transcription of coding genes by demethylating H4K20me1 and the transcription of repetitive elements by demethylating H4K20me3 (PubMed:32209475). Multiubiquitin chain receptor involved in modulation of proteasomal degradation. Binds to polyubiquitin chains. Proposed to be capable to bind simultaneously to the 26S proteasome and to polyubiquitinated substrates and to deliver ubiquitinated proteins to the proteasome (PubMed:10488153, PubMed:19435460). May play a role in endoplasmic reticulum-associated degradation (ERAD) of misfolded glycoproteins by association with PNGase and delivering deglycosylated proteins to the proteasome (PubMed:15358861). Involved in global genome nucleotide excision repair (GG-NER) by acting as component of the XPC complex, a nucleotide-excision repair complex that is involved in damage sensing during global genome nucleotide excision repair. In vitro, the XPC:RAD23B dimer is sufficient to initiate NER; it preferentially binds to cisplatin and UV-damaged double-stranded DNA. Recognizes a wide spectrum of damaged DNA characterized by distortions of the DNA helix including single-stranded loops, mismatched bubbles or single-stranded overhangs. Cooperatively with CETN2 appears to stabilize XPC (PubMed:10873465, PubMed:12815074, PubMed:9372924)","subunit":"Component of the XPC complex composed of XPC, RAD23B and CETN2 (PubMed:11279143, PubMed:12509233). Interacts with NGLY1 and PSMC1 (PubMed:15358861). Interacts with ATXN3 (PubMed:30455355). Interacts with PSMD4 and PSMC5 (PubMed:10488153). Interacts with AMFR (By similarity)","family":"Belongs to the RAD23 family","domains":[],"function_pmids":["10488153","10873465","12815074","15358861","19435460","32209475","9372924"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Multifunctional protein that participates in histone H4K20 demethylation, DNA repair, ubiquitin-dependent protein degradation and transcriptional regulation (PubMed:10488153, PubMed:32209475, PubMed:9372924). Specifically demethylates mono-, di- and trimethylated 'Lys-20' of histone H4 (H4K20me1, H4K20me2, H4K20me3, respectively) into unmethylated forms. Activates the transcription of coding genes by demethylating H4K20me1 and the transcription of repetitive elements by demethylating H4K20me3 (PubMed:32209475). Multiubiquitin chain receptor involved in modulation of proteasomal degradation. Binds to polyubiquitin chains. Proposed to be capable to bind simultaneously to the 26S proteasome and to polyubiquitinated substrates and to deliver ubiquitinated proteins to the proteasome (PubMed:10488153, PubMed:19435460). May play a role in endoplasmic reticulum-associated degradation (ERAD) of misfolded glycoproteins by association with PNGase and delivering deglycosylated proteins to the proteasome (PubMed:15358861). Involved in global genome nucleotide excision repair (GG-NER) by acting as component of the XPC complex, a nucleotide-excision repair complex that is involved in damage sensing during global genome nucleotide excision repair. In vitro, the XPC:RAD23B dimer is sufficient to initiate NER; it preferentially binds to cisplatin and UV-damaged double-stranded DNA. Recognizes a wide spectrum of damaged DNA characterized by distortions of the DNA helix including single-stranded loops, mismatched bubbles or single-stranded overhangs. Cooperatively with CETN2 appears to stabilize XPC (PubMed:10873465, PubMed:12815074, PubMed:9372924)"},"RAD50":{"hgnc":"HGNC:9816","symbol":"RAD50","accessions":["Q92878"],"name":"DNA repair protein RAD50","length":"1312","function":"Component of the MRN complex, which plays a central role in double-strand break (DSB) repair, DNA recombination, maintenance of telomere integrity and meiosis (PubMed:15064416, PubMed:21757780, PubMed:27889449, PubMed:28134932, PubMed:28867292, PubMed:9590181, PubMed:9651580, PubMed:9705271). The MRN complex is involved in the repair of DNA double-strand breaks (DSBs) via homologous recombination (HR), an error-free mechanism which primarily occurs during S and G2 phases (PubMed:15064416, PubMed:21757780, PubMed:27889449, PubMed:28867292, PubMed:9590181, PubMed:9651580, PubMed:9705271). The complex (1) mediates the end resection of damaged DNA, which generates proper single-stranded DNA, a key initial steps in HR, and is (2) required for the recruitment of other repair factors and efficient activation of ATM and ATR upon DNA damage (PubMed:15064416, PubMed:27889449, PubMed:28867292, PubMed:9590181, PubMed:9651580, PubMed:9705271). The MRN complex possesses single-strand endonuclease activity and double-strand-specific 3'-5' exonuclease activity, which are provided by MRE11, to initiate end resection, which is required for single-strand invasion and recombination (PubMed:11741547, PubMed:9590181, PubMed:9651580, PubMed:9705271). Within the complex, RAD50 is both required to bind DNA ends and hold them in close proximity and regulate the activity of MRE11 (PubMed:11741547, PubMed:12805565, PubMed:28134932). RAD50 provides an ATP-dependent control of MRE11 by positioning DNA ends into the MRE11 active site: ATP-binding induces a large structural change from an open form with accessible MRE11 nuclease sites into a closed form (By similarity). The MRN complex is also required for DNA damage signaling via activation of the ATM and ATR kinases: the nuclease activity of MRE11 is not required to activate ATM and ATR (PubMed:15064416, PubMed:15790808, PubMed:16622404). The MRN complex is also required for the processing of R-loops (PubMed:31537797). In telomeres the MRN complex may modulate t-loop formation (PubMed:10888888)","subunit":"Component of the MRN complex composed of two heterodimers RAD50 and MRE11 associated with a single NBN (PubMed:10839544, PubMed:26215093, PubMed:28867292, PubMed:36577401, PubMed:8756642, PubMed:9590181, PubMed:9705271). The MRN complexes dimerize on DNA to form joined MRN-MRN oligomers required for DNA double-strand break repair (PubMed:36577401). As part of the MRN complex, interacts with MCM8 and MCM9; the interaction recruits the complex to DNA repair sites (PubMed:26215093). Component of the BASC complex, at least composed of BRCA1, MSH2, MSH6, MLH1, ATM, BLM, RAD50, MRE11 and NBN (PubMed:10783165). Found in a complex with TERF2 (PubMed:10888888). Interacts with RINT1 (PubMed:11096100). Interacts with BRCA1 via its N-terminal domain (PubMed:10426999). Interacts with DCLRE1C/Artemis (PubMed:15456891, PubMed:15723659). Interacts with MRNIP (PubMed:27568553). Interacts with CYREN (via XLF motif) (By similarity). Interacts with C1QBP and MRE11; interaction takes place in absence of DNA damage to form the MRC (MRE11-RAD50-C1QBP) complex that inhibits the activity of MRE11 (PubMed:31353207)\n(Microbial infection) Interacts with herpes simplex virus 1 protein UL12 (PubMed:20943970)","family":"Belongs to the SMC family. RAD50 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10888888","11741547","12805565","15064416","15790808","16622404","21757780","27889449","28134932","28867292","31537797","9590181","9651580","9705271"],"location":"Nucleus；Chromosome, telomere；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；激酶/磷酸化信号；注释原文：Component of the MRN complex, which plays a central role in double-strand break (DSB) repair, DNA recombination, maintenance of telomere integrity and meiosis (PubMed:15064416, PubMed:21757780, PubMed:27889449, PubMed:28134932, PubMed:28867292, PubMed:9590181, PubMed:9651580, PubMed:9705271).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"DNA修复/复制；激酶/磷酸化信号"},"RAD51AP1":{"hgnc":"HGNC:16956","symbol":"RAD51AP1","accessions":["Q96B01"],"name":"RAD51-associated protein 1","length":"352","function":"Structure-specific DNA-binding protein involved in DNA repair by promoting RAD51-mediated homologous recombination (PubMed:17996710, PubMed:17996711, PubMed:20871616, PubMed:25288561, PubMed:26323318). Acts by stimulating D-Loop formation by RAD51: specifically enhances joint molecule formation through its structure-specific DNA interaction and its interaction with RAD51 (PubMed:17996710, PubMed:17996711). Binds single-stranded DNA (ssDNA), double-stranded DNA (dsDNA) and secondary DNA structures, such as D-loop structures: has a strong preference for branched-DNA structures that are obligatory intermediates during joint molecule formation (PubMed:17996710, PubMed:17996711, PubMed:22375013, PubMed:9396801). Cooperates with WDR48/UAF1 to stimulate RAD51-mediated homologous recombination: both WDR48/UAF1 and RAD51AP1 have coordinated role in DNA-binding during homologous recombination and DNA repair (PubMed:27239033, PubMed:27463890, PubMed:32350107). WDR48/UAF1 and RAD51AP1 also have a coordinated role in DNA-binding to promote USP1-mediated deubiquitination of FANCD2 (PubMed:31253762). Also involved in meiosis by promoting DMC1-mediated homologous meiotic recombination (PubMed:21307306). Key mediator of alternative lengthening of telomeres (ALT) pathway, a homology-directed repair mechanism of telomere elongation that controls proliferation in aggressive cancers, by stimulating homologous recombination (PubMed:31400850). May also bind RNA; additional evidence is however required to confirm RNA-binding in vivo (PubMed:9396801)","subunit":"Monomer; elongated monodisperse monomer (PubMed:17996710). Interacts (via C-terminal region) with RAD51; the interaction is direct (PubMed:16990250, PubMed:17996710, PubMed:17996711, PubMed:21903585, PubMed:23754376, PubMed:9396801). Interacts (via SIM motif) with WDR48/UAF1; WDR48/UAF1 and RAD51AP1 cooperate together to stimulate RAD51-mediated homologous recombination (HR) (PubMed:27239033, PubMed:27463890). Interacts (via WVPP motif) with DMC1; the interaction is direct (PubMed:21307306, PubMed:21903585). Interacts with PALB2 (PubMed:20871616). Interacts with RAD52 (PubMed:31400850)\nDoes not interact with DMC1; lack of interaction is caused by the absence of the WVPP motif in this isoform","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17996710","17996711","20871616","21307306","22375013","25288561","26323318","27239033","27463890","31253762","31400850","32350107","9396801"],"location":"Chromosome；Nucleus；Chromosome, telomere","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；注释原文：Structure-specific DNA-binding protein involved in DNA repair by promoting RAD51-mediated homologous recombination (PubMed:17996710, PubMed:17996711, PubMed:20871616, PubMed:25288561, PubMed:26323318).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制"},"RAD51B":{"hgnc":"HGNC:9822","symbol":"RAD51B","accessions":["O15315"],"name":"DNA repair protein RAD51 homolog 2","length":"384","function":"Involved in the homologous recombination repair (HRR) pathway of double-stranded DNA breaks arising during DNA replication or induced by DNA-damaging agents. May promote the assembly of presynaptic RAD51 nucleoprotein filaments. Binds single-stranded DNA and double-stranded DNA and has DNA-dependent ATPase activity. Part of the RAD51 paralog protein complex BCDX2 which acts in the BRCA1-BRCA2-dependent HR pathway. Upon DNA damage, BCDX2 acts downstream of BRCA2 recruitment and upstream of RAD51 recruitment. BCDX2 binds predominantly to the intersection of the four duplex arms of the Holliday junction and to junction of replication forks. The BCDX2 complex was originally reported to bind single-stranded DNA, single-stranded gaps in duplex DNA and specifically to nicks in duplex DNA. The BCDX2 subcomplex RAD51B:RAD51C exhibits single-stranded DNA-dependent ATPase activity suggesting an involvement in early stages of the HR pathway","subunit":"Part of the BCDX2 complex consisting of RAD51B, RAD51C, RAD51D and XRCC2; the complex has a ring-like structure arranged into a flat disc around a central channel (PubMed:11744692, PubMed:11751635, PubMed:11751636, PubMed:11842112, PubMed:11842113, PubMed:12427746, PubMed:14704354). The BCDX2 subcomplex RAD51B:RAD51C interacts with RAD51 (PubMed:11744692, PubMed:11751635, PubMed:11751636, PubMed:11842112, PubMed:11842113, PubMed:12427746, PubMed:14704354). Interacts with SWSAP1; involved in homologous recombination repair (PubMed:21965664). Interacts with HELQ (PubMed:24005041)","family":"Belongs to the RecA family. RAD51 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11751635","11751636","11842113","12441335","23108668","23149936"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；黏附/受体/细胞表面；注释原文：Involved in the homologous recombination repair (HRR) pathway of double-stranded DNA breaks arising during DNA replication or induced by DNA-damaging agents.","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制；黏附/受体/细胞表面"},"RAD51C":{"hgnc":"HGNC:9820","symbol":"RAD51C","accessions":["O43502"],"name":"DNA repair protein RAD51 homolog 3","length":"376","function":"Essential for the homologous recombination (HR) pathway of DNA repair. Involved in the homologous recombination repair (HRR) pathway of double-stranded DNA breaks arising during DNA replication or induced by DNA-damaging agents. Part of the RAD51 paralog protein complexes BCDX2 and CX3 which act at different stages of the BRCA1-BRCA2-dependent HR pathway. Upon DNA damage, BCDX2 seems to act downstream of BRCA2 recruitment and upstream of RAD51 recruitment; CX3 seems to act downstream of RAD51 recruitment; both complexes bind predominantly to the intersection of the four duplex arms of the Holliday junction (HJ) and to junction of replication forks. The BCDX2 complex was originally reported to bind single-stranded DNA, single-stranded gaps in duplex DNA and specifically to nicks in duplex DNA. The BCDX2 subcomplex RAD51B:RAD51C exhibits single-stranded DNA-dependent ATPase activity suggesting an involvement in early stages of the HR pathway. Involved in RAD51 foci formation in response to DNA damage suggesting an involvement in early stages of HR probably in the invasion step. Has an early function in DNA repair in facilitating phosphorylation of the checkpoint kinase CHEK2 and thereby transduction of the damage signal, leading to cell cycle arrest and HR activation. Participates in branch migration and HJ resolution and thus is important for processing HR intermediates late in the DNA repair process; the function may be linked to the CX3 complex. Part of a PALB2-scaffolded HR complex containing BRCA2 and which is thought to play a role in DNA repair by HR. Protects RAD51 from ubiquitin-mediated degradation that is enhanced following DNA damage. Plays a role in regulating mitochondrial DNA copy number under conditions of oxidative stress in the presence of RAD51 and XRCC3. Contributes to DNA cross-link resistance, sister chromatid cohesion and genomic stability. Involved in maintaining centrosome number in mitosis","subunit":"Part of the RAD51 paralog protein complexes BCDX2 and CX3; the complexes have a ring-like structure arranged into a flat disc around a central channel (PubMed:11751635, PubMed:11751636, PubMed:11842112, PubMed:11842113, PubMed:12427746, PubMed:14704354). The BCDX2 complex consits of RAD51B, RAD51C, RAD51D and XRCC2; the CX3 complex consists of RAD51C and XRCC3 (PubMed:11751635, PubMed:11842113, PubMed:14704354). The BCDX2 subcomplex RAD51B:RAD51C interacts with RAD51 (PubMed:12427746, PubMed:16395335). Interacts with SWSAP1; involved in homologous recombination repair (PubMed:21965664). Interacts directly with PALB2 which may serve as a scaffold for a HR complex containing PALB2, BRCA2, RAD51C, RAD51 and XRCC3 (PubMed:24141787). Interacts with HELQ (PubMed:24005041). Interacts with DNA damage up-regulated protein DDUP (PubMed:35849344)","family":"Belongs to the RecA family. RAD51 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14716019","16215984","16395335","19451272","19783859","20413593","23108668","23149936"],"location":"Nucleus；Cytoplasm；Cytoplasm, perinuclear region；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：Essential for the homologous recombination (HR) pathway of DNA repair.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"RAD51D":{"hgnc":"HGNC:9823","symbol":"RAD51D","accessions":["O75771"],"name":"DNA repair protein RAD51 homolog 4","length":"328","function":"Involved in the homologous recombination repair (HRR) pathway of double-stranded DNA breaks arising during DNA replication or induced by DNA-damaging agents. Bind to single-stranded DNA (ssDNA) and has DNA-dependent ATPase activity. Part of the RAD51 paralog protein complex BCDX2 which acts in the BRCA1-BRCA2-dependent HR pathway. Upon DNA damage, BCDX2 acts downstream of BRCA2 recruitment and upstream of RAD51 recruitment. BCDX2 binds predominantly to the intersection of the four duplex arms of the Holliday junction and to junction of replication forks. The BCDX2 complex was originally reported to bind single-stranded DNA, single-stranded gaps in duplex DNA and specifically to nicks in duplex DNA. Involved in telomere maintenance. The BCDX2 subcomplex XRCC2:RAD51D can stimulate Holliday junction resolution by BLM","subunit":"Part of the BCDX2 complex consisting of RAD51B, RAD51C, RAD51D and XRCC2; the complex has a ring-like structure arranged into a flat disc around a central channel. In the absence of DNA, the BCDX2 subcomplex XRCC2:RAD51D formed a multimeric ring structure; in the presence of single-stranded DNA it formed a filamentous structure with the ssDNA. Interacts with SWSAP1 and ZSWIM7; involved in homologous recombination repair. Interacts with BLM; required for stimulation of BLM activity by the BCDX2 subcomplex XRCC2:RAD51D","family":"Belongs to the RecA family. RAD51 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10871607","11751635","11834724","11842113","12975363","15109494","23149936"],"location":"Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Chromosome, telomere","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；注释原文：Involved in the homologous recombination repair (HRR) pathway of double-stranded DNA breaks arising during DNA replication or induced by DNA-damaging agents.","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制"},"RADIL":{"hgnc":"HGNC:22226","symbol":"RADIL","accessions":["Q96JH8"],"name":"Ras-associating and dilute domain-containing protein","length":"1075","function":"Downstream effector of Rap required for cell adhesion and migration of neural crest precursors during development","subunit":"Interacts with RAP1A; in a GTP-dependent manner. Does not interact with members of the Ras family (PubMed:17704304). Interacts (via PDZ domain) with KIF14; is recruited to the microtubule network restricting its interaction with activated RAP1A (PubMed:23209302)","family":"Belongs to the RADIL family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17704304"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；发育/分化；注释原文：Downstream effector of Rap required for cell adhesion and migration of neural crest precursors during development","function_evidence":"含实验支持条目；ECO:0000269","categories":"黏附/受体/细胞表面；发育/分化"},"RAE1":{"hgnc":"HGNC:9828","symbol":"RAE1","accessions":["P78406"],"name":"mRNA export factor RAE1","length":"368","function":"Acts as a mRNA export factor involved in nucleocytoplasmic transport (PubMed:20498086, PubMed:33849972). Plays a role in mitotic bipolar spindle formation (PubMed:17172455). May function in attaching cytoplasmic mRNPs to the cytoskeleton both directly or indirectly (PubMed:17172455)","subunit":"Interacts with NUMA1 (via N-terminal end of the coiled-coil domain); this interaction promotes spindle formation in mitosis (PubMed:17172455). Interacts with NUP98 (PubMed:20498086). Interacts with MYCBP2 (PubMed:22357847). Interacts with USP11 (PubMed:29293652)\n(Microbial infection) Interacts with SARS coronavirus-2/SARS-CoV-2 ORF6 protein; the interaction displaces RAE1 from the nuclear envelope and impairs its role in nucleocytoplasmic transport\n(Microbial infection) Interacts with SARS coronavirus/SARS-CoV ORF6 protein","family":"Belongs to the WD repeat rae1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17172455","20498086","33849972"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, spindle pole；Nucleus envelope","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；细胞周期/分裂；细胞骨架/纤毛；注释原文：Acts as a mRNA export factor involved in nucleocytoplasmic transport (PubMed:20498086, PubMed:33849972).","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；细胞周期/分裂；细胞骨架/纤毛"},"RAF1":{"hgnc":"HGNC:9829","symbol":"RAF1","accessions":["P04049"],"name":"RAF proto-oncogene serine/threonine-protein kinase","length":"648","function":"Serine/threonine-protein kinase that acts as a regulatory link between the membrane-associated Ras GTPases and the MAPK/ERK cascade, and this critical regulatory link functions as a switch determining cell fate decisions including proliferation, differentiation, apoptosis, survival and oncogenic transformation. RAF1 activation initiates a mitogen-activated protein kinase (MAPK) cascade that comprises a sequential phosphorylation of the dual-specific MAPK kinases (MAP2K1/MEK1 and MAP2K2/MEK2) and the extracellular signal-regulated kinases (MAPK3/ERK1 and MAPK1/ERK2). The phosphorylated form of RAF1 (on residues Ser-338 and Ser-339, by PAK1) phosphorylates BAD/Bcl2-antagonist of cell death at 'Ser-75'. Phosphorylates adenylyl cyclases: ADCY2, ADCY5 and ADCY6, resulting in their activation. Phosphorylates PPP1R12A resulting in inhibition of the phosphatase activity. Phosphorylates TNNT2/cardiac muscle troponin T. Can promote NF-kB activation and inhibit signal transducers involved in motility (ROCK2), apoptosis (MAP3K5/ASK1 and STK3/MST2), proliferation and angiogenesis (RB1). Can protect cells from apoptosis also by translocating to the mitochondria where it binds BCL2 and displaces BAD/Bcl2-antagonist of cell death. Regulates Rho signaling and migration, and is required for normal wound healing. Plays a role in the oncogenic transformation of epithelial cells via repression of the TJ protein, occludin (OCLN) by inducing the up-regulation of a transcriptional repressor SNAI2/SLUG, which induces down-regulation of OCLN. Restricts caspase activation in response to selected stimuli, notably Fas stimulation, pathogen-mediated macrophage apoptosis, and erythroid differentiation","subunit":"Monomer. Homodimer. Heterodimerizes with BRAF and this heterodimer possesses a highly increased kinase activity compared to the respective homodimers or monomers (PubMed:16508002). Heterodimerization is mitogen-regulated and enhanced by 14-3-3 proteins (PubMed:16508002). MAPK1/ERK2 activation can induce a negative feedback that promotes the dissociation of the heterodimer (PubMed:16508002). Forms a multiprotein complex with Ras (M-Ras/MRAS), SHOC2 and protein phosphatase 1 (PPP1CA, PPP1CB and PPP1CC) (PubMed:16630891). Interacts with LZTR1 (PubMed:30368668). Interacts with Ras proteins; the interaction is antagonized by RIN1 (PubMed:11784866). Weakly interacts with RIT1. Interacts (via N-terminus) with RGS14 (via RBD domains); the interaction mediates the formation of a ternary complex with BRAF, a ternary complex inhibited by GNAI1 (By similarity). Probably forms a complex composed of chaperones HSP90 and HSP70, co-chaperones CDC37, PPP5C, TSC1 and client protein TSC2, CDK4, AKT, RAF1 and NR3C1; this complex does not contain co-chaperones STIP1/HOP and PTGES3/p23 (PubMed:29127155). Interacts with STK3/MST2; the interaction inhibits its pro-apoptotic activity (PubMed:15618521). Interacts (when phosphorylated at Ser-259) with YWHAZ (unphosphorylated at 'Thr-232') (PubMed:31024343, PubMed:9360956). Interacts with MAP2K1/MEK1 and MAP2K2/MEK2 (By similarity). Interacts with MAP3K5/ASF1 (via N-terminus) and this interaction inhibits the proapoptotic function of MAP3K5/ASK1 (PubMed:11427728). Interacts with PAK1 (via kinase domain) (PubMed:11733498). The phosphorylated form interacts with PIN1 (By similarity). The Ser-338 and Ser-339 phosphorylated form (by PAK1) interacts with BCL2 (PubMed:15849194). Interacts with PEBP1/RKIP and this interaction is enhanced if RAF1 is phosphorylated on residues Ser-338, Ser-339, Tyr-340 and Tyr-341 (PubMed:18294816). Interacts with ADCY2, ADCY5, ADCY6, DGKH, RCAN1/DSCR1, PPP1R12A, PKB/AKT1, PPP2CA, PPP2R1B, SPRY2, SPRY4, CNKSR1/CNK1, KSR2 and PHB/prohibitin (PubMed:10576742, PubMed:10801873, PubMed:11719507, PubMed:12717443, PubMed:15385642, PubMed:15935327, PubMed:19710016). Interacts with ROCK2 (By similarity). In its active form, interacts with PRMT5 (PubMed:21917714). Interacts with CSNK1B; displaces 14-3-3 proteins from RAF1 and activates RAF1 (PubMed:22886302). Interacts with PDE8A; the interaction promotes RAF1 activity (PubMed:23509299). Interacts with MFHAS1 (PubMed:23327923). Interacts with GLS (PubMed:22538822). Interacts with NEK10 and MAP2K1; the interaction is direct with NEK10 and required for ERK1/2-signaling pathway activation in response to UV irradiation (PubMed:20956560)","family":"Belongs to the protein kinase superfamily. TKL Ser/Thr protein kinase family. RAF subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11427728","11719507","15385642","15618521","15849194","16892053","16924233","9360956"],"location":"Cytoplasm；Cell membrane；Mitochondrion；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Serine/threonine-protein kinase that acts as a regulatory link between the membrane-associated Ras GTPases and the MAPK/ERK cascade, and this critical regulatory link functions as a switch determining cell fate decisions including proliferation, differentiation, apoptosis, survival and oncogenic transformation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"RAG1":{"hgnc":"HGNC:9831","symbol":"RAG1","accessions":["P15918"],"name":"V(D)J recombination-activating protein 1","length":"1043","function":"Catalytic component of the RAG complex, a multiprotein complex that mediates the DNA cleavage phase during V(D)J recombination. V(D)J recombination assembles a diverse repertoire of immunoglobulin and T-cell receptor genes in developing B and T-lymphocytes through rearrangement of different V (variable), in some cases D (diversity), and J (joining) gene segments. In the RAG complex, RAG1 mediates the DNA-binding to the conserved recombination signal sequences (RSS) and catalyzes the DNA cleavage activities by introducing a double-strand break between the RSS and the adjacent coding segment. RAG2 is not a catalytic component but is required for all known catalytic activities. DNA cleavage occurs in 2 steps: a first nick is introduced in the top strand immediately upstream of the heptamer, generating a 3'-hydroxyl group that can attack the phosphodiester bond on the opposite strand in a direct transesterification reaction, thereby creating 4 DNA ends: 2 hairpin coding ends and 2 blunt, 5'-phosphorylated ends. The chromatin structure plays an essential role in the V(D)J recombination reactions and the presence of histone H3 trimethylated at 'Lys-4' (H3K4me3) stimulates both the nicking and haipinning steps. The RAG complex also plays a role in pre-B cell allelic exclusion, a process leading to expression of a single immunoglobulin heavy chain allele to enforce clonality and monospecific recognition by the B-cell antigen receptor (BCR) expressed on individual B-lymphocytes. The introduction of DNA breaks by the RAG complex on one immunoglobulin allele induces ATM-dependent repositioning of the other allele to pericentromeric heterochromatin, preventing accessibility to the RAG complex and recombination of the second allele. In addition to its endonuclease activity, RAG1 also acts as an E3 ubiquitin-protein ligase that mediates monoubiquitination of histone H3. Histone H3 monoubiquitination is required for the joining step of V(D)J recombination. Mediates polyubiquitination of KPNA1 (By similarity)","subunit":"Homodimer. Component of the RAG complex composed of core components RAG1 and RAG2, and associated component HMGB1 or HMGB2. Interacts with DCAF1, leading to recruitment of the CUL4A-RBX1-DDB1-DCAF1/VPRBP complex to ubiquitinate proteins and limit error-prone repair during V(D)J recombination (By similarity)","family":"Belongs to the RAG1 family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Catalytic component of the RAG complex, a multiprotein complex that mediates the DNA cleavage phase during V(D)J recombination. V(D)J recombination assembles a diverse repertoire of immunoglobulin and T-cell receptor genes in developing B and T-lymphocytes through rearrangement of different V (variable), in some cases D (diversity), and J (joining) gene segments. In the RAG complex, RAG1 mediates the DNA-binding to the conserved recombination signal sequences (RSS) and catalyzes the DNA cleavage activities by introducing a double-strand break between the RSS and the adjacent coding segment. RAG2 is not a catalytic component but is required for all known catalytic activities. DNA cleavage occurs in 2 steps: a first nick is introduced in the top strand immediately upstream of the heptamer, generating a 3'-hydroxyl group that can attack the phosphodiester bond on the opposite strand in a direct transesterification reaction, thereby creating 4 DNA ends: 2 hairpin coding ends and 2 blunt, 5'-phosphorylated ends. The chromatin structure plays an essential role in the V(D)J recombination reactions and the presence of histone H3 trimethylated at 'Lys-4' (H3K4me3) stimulates both the nicking and haipinning steps. The RAG complex also plays a role in pre-B cell allelic exclusion, a process leading to expression of a single immunoglobulin heavy chain allele to enforce clonality and monospecific recognition by the B-cell antigen receptor (BCR) expressed on individual B-lymphocytes. The introduction of DNA breaks by the RAG complex on one immunoglobulin allele induces ATM-dependent repositioning of the other allele to pericentromeric heterochromatin, preventing accessibility to the RAG complex and recombination of the second allele. In addition to its endonuclease activity, RAG1 also acts as an E3 ubiquitin-protein ligase that mediates monoubiquitination of histone H3. Histone H3 monoubiquitination is required for the joining step of V(D)J recombination. Mediates polyubiquitination of KPNA1 (By similarity)"},"RAG2":{"hgnc":"HGNC:9832","symbol":"RAG2","accessions":["P55895"],"name":"V(D)J recombination-activating protein 2","length":"527","function":"Core component of the RAG complex, a multiprotein complex that mediates the DNA cleavage phase during V(D)J recombination. V(D)J recombination assembles a diverse repertoire of immunoglobulin and T-cell receptor genes in developing B and T-lymphocytes through rearrangement of different V (variable), in some cases D (diversity), and J (joining) gene segments. DNA cleavage by the RAG complex occurs in 2 steps: a first nick is introduced in the top strand immediately upstream of the heptamer, generating a 3'-hydroxyl group that can attack the phosphodiester bond on the opposite strand in a direct transesterification reaction, thereby creating 4 DNA ends: 2 hairpin coding ends and 2 blunt, 5'-phosphorylated ends. The chromatin structure plays an essential role in the V(D)J recombination reactions and the presence of histone H3 trimethylated at 'Lys-4' (H3K4me3) stimulates both the nicking and haipinning steps. The RAG complex also plays a role in pre-B cell allelic exclusion, a process leading to expression of a single immunoglobulin heavy chain allele to enforce clonality and monospecific recognition by the B-cell antigen receptor (BCR) expressed on individual B-lymphocytes. The introduction of DNA breaks by the RAG complex on one immunoglobulin allele induces ATM-dependent repositioning of the other allele to pericentromeric heterochromatin, preventing accessibility to the RAG complex and recombination of the second allele. In the RAG complex, RAG2 is not the catalytic component but is required for all known catalytic activities mediated by RAG1. It probably acts as a sensor of chromatin state that recruits the RAG complex to H3K4me3 (By similarity)","subunit":"Component of the RAG complex composed of core components RAG1 and RAG2, and associated component HMGB1 or HMGB2","family":"Belongs to the RAG2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；黏附/受体/细胞表面；注释原文：Core component of the RAG complex, a multiprotein complex that mediates the DNA cleavage phase during V(D)J recombination.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；激酶/磷酸化信号；黏附/受体/细胞表面"},"RAI1":{"hgnc":"HGNC:9834","symbol":"RAI1","accessions":["Q7Z5J4"],"name":"Retinoic acid-induced protein 1","length":"1906","function":"Transcriptional regulator of the circadian clock components: CLOCK, BMAL1, BMAL2, PER1/3, CRY1/2, NR1D1/2 and RORA/C. Positively regulates the transcriptional activity of CLOCK a core component of the circadian clock. Regulates transcription through chromatin remodeling by interacting with other proteins in chromatin as well as proteins in the basic transcriptional machinery. May be important for embryonic and postnatal development. May be involved in neuronal differentiation","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22578325"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Transcriptional regulator of the circadian clock components: CLOCK, BMAL1, BMAL2, PER1/3, CRY1/2, NR1D1/2 and RORA/C.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；发育/分化"},"RAI14":{"hgnc":"HGNC:14873","symbol":"RAI14","accessions":["Q9P0K7"],"name":"Ankycorbin","length":"980","function":"Plays a role in actin regulation at the ectoplasmic specialization, a type of cell junction specific to testis. Important for establishment of sperm polarity and normal spermatid adhesion. May also promote integrity of Sertoli cell tight junctions at the blood-testis barrier","subunit":"Interacts with PALLD. Associates with actin. However, does not bind F-actin directly","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm, cytoskeleton；Cytoplasm, cytoskeleton, stress fiber；Cytoplasm, cell cortex；Cell junction；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞骨架/纤毛；注释原文：Plays a role in actin regulation at the ectoplasmic specialization, a type of cell junction specific to testis.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"细胞骨架/纤毛"},"RALBP1":{"hgnc":"HGNC:9841","symbol":"RALBP1","accessions":["Q15311"],"name":"RalA-binding protein 1","length":"655","function":"Multifunctional protein that functions as a downstream effector of RALA and RALB (PubMed:7673236). As a GTPase-activating protein/GAP can inactivate CDC42 and RAC1 by stimulating their GTPase activity (PubMed:7673236). As part of the Ral signaling pathway, may also regulate ligand-dependent EGF and insulin receptors-mediated endocytosis (PubMed:10910768, PubMed:12775724). During mitosis, may act as a scaffold protein in the phosphorylation of EPSIN/EPN1 by the mitotic kinase cyclin B-CDK1, preventing endocytosis during that phase of the cell cycle (PubMed:12775724). During mitosis, also controls mitochondrial fission as an effector of RALA (PubMed:21822277). Recruited to mitochondrion by RALA, acts as a scaffold to foster the mitotic kinase cyclin B-CDK1-mediated phosphorylation and activation of DNM1L (PubMed:21822277)\nCould also function as a primary ATP-dependent active transporter for glutathione conjugates of electrophiles. May also actively catalyze the efflux of a wide range of substrates including xenobiotics like doxorubicin (DOX) contributing to cell multidrug resistance","subunit":"Interacts with the GTP-bound form of RALA (via effector domain); during mitosis, recruits RALBP1 to the mitochondrion where it promotes DNM1L phosphorylation and mitochondrial fission (PubMed:21822277, PubMed:7673236). Interacts with DNM1L; mediates its mitotic kinase cyclin B-CDK1-mediated phosphorylation during mitosis to promote mitochondrial fission (PubMed:21822277). Interacts with the mitotic kinase cyclin B-CDK1 during mitosis (PubMed:12775724, PubMed:21822277). Interacts with the GTP-bound form of RALB (via effector domain) (PubMed:20696399, PubMed:7673236). Interacts with REPS1; the interaction is direct and does not affect RALA-binding nor GTPase activator activity of RALBP1 (By similarity). Interacts with REPS2; the interaction is direct and does not affect RALA-binding nor GTPase activator activity of RALBP1 (PubMed:9422736). Interacts with EPN1, NUMB and TFAP2A during interphase and mitosis (PubMed:12775724). Interacts with AP2M1; as part of the AP2 complex (PubMed:10910768). Interacts with CDC42 (Probable). Interacts with RAC1 (PubMed:7673236)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10910768","10924126","11300797","11437348","12775724","21822277","7673236","9548755"],"location":"Cell membrane；Peripheral membrane protein；Cytoplasm, cytosol；Cytoplasm, cytoskeleton, spindle pole；Nucleus；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面；注释原文：Multifunctional protein that functions as a downstream effector of RALA and RALB (PubMed:7673236).","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面"},"RALGDS":{"hgnc":"HGNC:9842","symbol":"RALGDS","accessions":["Q12967"],"name":"Ral guanine nucleotide dissociation stimulator","length":"914","function":"Functions as a guanine nucleotide exchange factor (GEF) activating either RalA or RalB GTPases and plays an important role in intracellular transport. Interacts and acts as an effector molecule for R-Ras, H-Ras, K-Ras, and Rap (By similarity). During bacterial clearance, recognizes 'Lys-33'-linked polyubiquitinated TRAF3 and subsequently mediates assembly of the exocyst complex (PubMed:27438768)","subunit":"Interacts with RIT1 and RIT2 (By similarity). Interacts with OOG1 (By similarity). Interacts with TRAF3 (PubMed:27438768). Interacts with HRAS (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["27438768"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Functions as a guanine nucleotide exchange factor (GEF) activating either RalA or RalB GTPases and plays an important role in intracellular transport.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态"},"RALY":{"hgnc":"HGNC:15921","symbol":"RALY","accessions":["Q9UKM9"],"name":"RNA-binding protein Raly","length":"306","function":"RNA-binding protein that acts as a transcriptional cofactor for cholesterol biosynthetic genes in the liver. Binds the lipid-responsive non-coding RNA LeXis and is required for LeXis-mediated effect on cholesterogenesis (By similarity). May be a heterogeneous nuclear ribonucleoprotein (hnRNP) (PubMed:9376072)","subunit":"Identified in the spliceosome C complex (PubMed:11991638). Interacts (through its RNA-binding domain) with FUS (through its RNA-binding domain); both are components of the same RNPs (PubMed:30354839)","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9376072"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；线粒体/代谢；注释原文：RNA-binding protein that acts as a transcriptional cofactor for cholesterol biosynthetic genes in the liver.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；线粒体/代谢"},"RALYL":{"hgnc":"HGNC:27036","symbol":"RALYL","accessions":["Q86SE5"],"name":"RNA-binding Raly-like protein","length":"291","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"RAMAC":{"hgnc":"HGNC:31022","symbol":"RAMAC","accessions":["Q9BTL3"],"name":"RNA guanine-N7 methyltransferase activating subunit","length":"118","function":"Regulatory subunit of the mRNA-capping methyltransferase RNMT:RAMAC complex that methylates the N7 position of the added guanosine to the 5'-cap structure of mRNAs (PubMed:22099306, PubMed:27422871). Promotes the recruitment of the methyl donor, S-adenosyl-L-methionine, to RNMT (PubMed:27422871). Regulates RNMT expression by a post-transcriptional stabilizing mechanism (PubMed:22099306). Binds RNA (PubMed:22099306)","subunit":"Interacts with RNMT; this interaction enhances mRNA binding and cap methyltransferase activity","family":"Belongs to the RAM family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22099306","27422871"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Regulatory subunit of the mRNA-capping methyltransferase RNMT:RAMAC complex that methylates the N7 position of the added guanosine to the 5'-cap structure of mRNAs (PubMed:22099306, PubMed:27422871).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"RAN":{"hgnc":"HGNC:9846","symbol":"RAN","accessions":["P62826"],"name":"GTP-binding nuclear protein Ran","length":"216","function":"GTPase involved in nucleocytoplasmic transport, participating both to the import and the export from the nucleus of proteins and RNAs (PubMed:10400640, PubMed:17209048, PubMed:26272610, PubMed:27306458, PubMed:8276887, PubMed:8636225, PubMed:8692944, PubMed:8896452, PubMed:9351834, PubMed:9428644, PubMed:9822603). Switches between a cytoplasmic GDP- and a nuclear GTP-bound state by nucleotide exchange and GTP hydrolysis (PubMed:11336674, PubMed:26272610, PubMed:29040603, PubMed:7819259, PubMed:8636225, PubMed:8692944, PubMed:8896452, PubMed:9351834, PubMed:9428644, PubMed:9822603). Nuclear import receptors such as importin beta bind their substrates only in the absence of GTP-bound RAN and release them upon direct interaction with GTP-bound RAN, while export receptors behave in the opposite way. Thereby, RAN controls cargo loading and release by transport receptors in the proper compartment and ensures the directionality of the transport (PubMed:8896452, PubMed:9351834, PubMed:9428644). Interaction with RANBP1 induces a conformation change in the complex formed by XPO1 and RAN that triggers the release of the nuclear export signal of cargo proteins (PubMed:20485264). RAN (GTP-bound form) triggers microtubule assembly at mitotic chromosomes and is required for normal mitotic spindle assembly and chromosome segregation (PubMed:10408446, PubMed:29040603). Required for normal progress through mitosis (PubMed:12194828, PubMed:29040603, PubMed:8421051). The complex with BIRC5/survivin plays a role in mitotic spindle formation by serving as a physical scaffold to help deliver the RAN effector molecule TPX2 to microtubules (PubMed:18591255). Acts as a negative regulator of the kinase activity of VRK1 and VRK2 (PubMed:18617507). Enhances AR-mediated transactivation. Transactivation decreases as the poly-Gln length within AR increases (PubMed:10400640)","subunit":"Monomer. Interacts with RANGAP1, which promotes RAN-mediated GTP hydrolysis (PubMed:7819259, PubMed:9428644). Interacts with KPNB1 (PubMed:10367892, PubMed:8896452, PubMed:9428644). Interaction with KPNB1 inhibits RANGAP1-mediated stimulation of GTPase activity (PubMed:9428644). Interacts with RCC1 which promotes the exchange of RAN-bound GDP by GTP (PubMed:11336674, PubMed:12194828, PubMed:1961752, PubMed:7819259). Interaction with KPNB1 inhibits RCC1-mediated exchange of RAN-bound GDP by GTP (PubMed:8896452). Interacts (GTP-bound form) with TNPO1; the interaction is direct (PubMed:9351834). Interacts (GTP-bound form) with TNPO3; the interaction is direct (PubMed:23878195, PubMed:24449914, PubMed:24915079). Interacts with KPNB1 and with TNPO1; both inhibit RAN GTPase activity (PubMed:8896452, PubMed:9428644). Interacts (via C-terminus) with RANBP1, which alleviates the inhibition of RAN GTPase activity (PubMed:11832950, PubMed:7891706, PubMed:8896452, PubMed:9428644). Interacts with RANGRF, which promotes the release of bound guanine nucleotide (PubMed:29040603). RANGRF and RCC1 compete for an overlapping binding site on RAN (PubMed:29040603). Identified in a complex with KPNA2 and CSE1L; interaction with RANBP1 mediates dissociation of RAN from this complex (PubMed:9428644). Interaction with both RANBP1 and KPNA2 promotes dissociation of the complex between RAN and KPNB1 (PubMed:9428644). Identified in a complex composed of RAN, RANGAP1 and RANBP1 (PubMed:16428860). Identified in a complex that contains TNPO1, RAN and RANBP1 (PubMed:9428644). Identified in a nuclear export complex with XPO1 (PubMed:10209022, PubMed:15574331, PubMed:9323133). Found in a nuclear export complex with RANBP3 and XPO1 (PubMed:11425870, PubMed:11571268). Interacts with RANBP2/NUP358 (PubMed:10078529, PubMed:26272610). Interaction with RANBP1 or RANBP2 induces a conformation change in the complex formed by XPO1 and RAN that triggers the release of the nuclear export signal of cargo proteins (PubMed:20485264). Component of a nuclear export receptor complex composed of KPNB1, RAN, SNUPN and XPO1 (PubMed:10209022, PubMed:19389996). Found in a nuclear export complex with RAN, XPO5 and pre-miRNA (By similarity). Interacts (GTP-bound form) with XPO5 (By similarity). Part of a complex consisting of RANBP9, RAN, DYRK1B and COPS5 (PubMed:14500717). Interacts with RANBP9 and RANBP10 (PubMed:14684163). Interacts in its GTP-bound form with BIRC5/survivin at S and M phases of the cell cycle (PubMed:18591255). Interacts with TERT; the interaction requires hydrogen peroxide-mediated phosphorylation of TERT and transports TERT to the nucleus (PubMed:12808100). Interacts with MAD2L2 (PubMed:19753112). Interacts with VRK1 and VRK3 (PubMed:18617507). Interacts with isoform 1 and isoform 2 of VRK2 (PubMed:18617507). Interacts with NEMP1 and KPNB1 (By similarity). Interacts (GDP-bound form) with NUTF2; regulates RAN nuclear import (PubMed:10679025, PubMed:18266911, PubMed:9822603). Interacts with CAPG; mediates CAPG nuclear import (PubMed:10679025, PubMed:18266911). Interacts with NUP153 (PubMed:18611384, PubMed:19505478). Interacts with the AR N-terminal poly-Gln region; the interaction with AR is inversely correlated with the poly-Gln length (PubMed:10400640). Interacts with MYCBP2, which promotes RAN-mediated GTP hydrolysis (PubMed:26304119). Interacts with EPG5 (PubMed:29130391)\n(Microbial infection) In case of HIV-1 infection, found in a complex with HIV-1 Rev, RNAs containing a Rev response element (RRE) and XPO1\n(Microbial infection) Found in a complex with HTLV-1 Rex, RANBP3 and XPO1\n(Microbial infection) Interacts with Mengo encephalomyocarditis virus Leader protein; the complex L-RAN recruits cellular kinases responsible for the L-induced nucleocytoplasmic trafficking inhibition","family":"Belongs to the small GTPase superfamily. Ran family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10400640","10408446","11336674","12194828","17209048","18591255","18617507","20485264","26272610","27306458","29040603","7819259","8276887","8421051","8636225","8692944","8896452","9351834","9428644","9822603"],"location":"Nucleus；Nucleus envelope；Cytoplasm, cytosol；Cytoplasm；Melanosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：GTPase involved in nucleocytoplasmic transport, participating both to the import and the export from the nucleus of proteins and RNAs (PubMed:10400640, PubMed:17209048, PubMed:26272610, PubMed:27306458, PubMed:8276887, PubMed:8636225, PubMed:8692944, PubMed:8896452, PubMed:9351834, PubMed:9428644, PubMed:9822603).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"核质运输；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面"},"RANBP1":{"hgnc":"HGNC:9847","symbol":"RANBP1","accessions":["P43487"],"name":"Ran-specific GTPase-activating protein","length":"201","function":"Plays a role in RAN-dependent nucleocytoplasmic transport. Alleviates the TNPO1-dependent inhibition of RAN GTPase activity and mediates the dissociation of RAN from proteins involved in transport into the nucleus (By similarity). Induces a conformation change in the complex formed by XPO1 and RAN that triggers the release of the nuclear export signal of cargo proteins (PubMed:20485264). Promotes the disassembly of the complex formed by RAN and importin beta. Promotes dissociation of RAN from a complex with KPNA2 and CSE1L (By similarity). Required for normal mitotic spindle assembly and normal progress through mitosis via its effect on RAN (PubMed:17671426). Does not increase the RAN GTPase activity by itself, but increases GTP hydrolysis mediated by RANGAP1 (PubMed:7882974). Inhibits RCC1-dependent exchange of RAN-bound GDP by GTP (PubMed:7616957, PubMed:7882974)","subunit":"Interacts with RAN (via C-terminus of GTP-bound form) but not with GDP-bound RAN (PubMed:7882974, PubMed:7891706, PubMed:8896452). Identified in a complex composed of RAN, RANGAP1 and RANBP1 (PubMed:11832950, PubMed:16428860). Identified in a complex that contains TNPO1, RAN and RANBP1. Identified in a complex that contains CSE1L, KPNA2, RAN and RANBP1 (By similarity). Identified in a complex with nucleotide-free RAN and RCC1 (PubMed:7616957, PubMed:7882974)","family":"Belongs to the RANBP1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17671426","20485264","7616957","7882974"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；细胞周期/分裂；注释原文：Plays a role in RAN-dependent nucleocytoplasmic transport.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"核质运输；细胞周期/分裂"},"RANBP10":{"hgnc":"HGNC:29285","symbol":"RANBP10","accessions":["Q6VN20"],"name":"Ran-binding protein 10","length":"620","function":"May act as an adapter protein to couple membrane receptors to intracellular signaling pathways (Probable). Core component of the CTLH E3 ubiquitin-protein ligase complex that selectively accepts ubiquitin from UBE2H and mediates ubiquitination and subsequent proteasomal degradation of the transcription factor HBP1 (PubMed:29911972). Enhances dihydrotestosterone-induced transactivation activity of AR, as well as dexamethasone-induced transactivation activity of NR3C1, but does not affect estrogen-induced transactivation (PubMed:18222118). Acts as a guanine nucleotide exchange factor (GEF) for RAN GTPase. May play an essential role in hemostasis and in maintaining microtubule dynamics with respect to both platelet shape and function (By similarity)","subunit":"May form homodimers (PubMed:18222118). Identified in the CTLH complex that contains GID4, RANBP9 and/or RANBP10, MKLN1, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, ARMC8, WDR26 and YPEL5 (PubMed:29911972). Within this complex, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, WDR26, and RANBP9 and/or RANBP10 form the catalytic core, while GID4, MKLN1, ARMC8 and YPEL5 have ancillary roles (PubMed:29911972). Interacts with RAN and RANBP9 (PubMed:14684163, PubMed:18222118). Interacts with the HGF receptor MET (PubMed:14684163). Interacts with AR (PubMed:18222118). Interacts with TUBB1 (PubMed:18347012). Interacts with YPEL5 (PubMed:20580816). May interact with TUBB5 (By similarity). Interacts with DDX4 (By similarity)","family":"Belongs to the RANBP9/10 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18222118","29911972"],"location":"Cytoplasm, cytosol；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：May act as an adapter protein to couple membrane receptors to intracellular signaling pathways (Probable).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞骨架/纤毛；黏附/受体/细胞表面"},"RANBP2":{"hgnc":"HGNC:9848","symbol":"RANBP2","accessions":["P49792"],"name":"E3 SUMO-protein ligase RanBP2","length":"3224","function":"E3 SUMO-protein ligase which facilitates SUMO1 and SUMO2 conjugation by UBE2I (PubMed:11792325, PubMed:12032081, PubMed:15378033, PubMed:15931224, PubMed:22194619). Involved in transport factor (Ran-GTP, karyopherin)-mediated protein import via the F-G repeat-containing domain which acts as a docking site for substrates (PubMed:7775481). Binds single-stranded RNA (in vitro) (PubMed:7775481). May bind DNA (PubMed:7775481). Component of the nuclear export pathway (PubMed:10078529). Specific docking site for the nuclear export factor exportin-1 (PubMed:10078529). Inhibits EIF4E-dependent mRNA export (PubMed:22902403). Sumoylates PML at 'Lys-490' which is essential for the proper assembly of PML-NB (PubMed:22155184). Recruits BICD2 to the nuclear envelope and cytoplasmic stacks of nuclear pore complex known as annulate lamellae during G2 phase of cell cycle (PubMed:20386726). Probable inactive PPIase with no peptidyl-prolyl cis-trans isomerase activity (PubMed:20676357, PubMed:23353830)","subunit":"Part of the nuclear pore complex (PubMed:11839768, PubMed:20386726, PubMed:23353830, PubMed:7603572). Forms a complex with NXT1, NXF1 and RANGAP1 (PubMed:14729961). Forms a tight complex with RANBP1 and UBE2I (PubMed:10078529, PubMed:15388847, PubMed:15826666). Interacts with SUMO1 but not SUMO2 (PubMed:10078529, PubMed:15388847, PubMed:15826666). Interacts with PRKN (PubMed:16332688). Interacts with sumoylated RANGAP1 (PubMed:10078529, PubMed:15378033, PubMed:15826666). Interacts with CDCA8 (PubMed:19413330). Interacts with PML (isoform PML-4) (PubMed:22155184). Interacts with BICD2 (PubMed:20386726). Interacts with MCM3AP isoform GANP (PubMed:20005110). Interacts with COX11 (PubMed:34400285). Interacts with synaptic plasticity regulator PANTS (By similarity)\n(Microbial infection) Interacts with HIV-1 Vpu protein; this interaction allows Vpu to down-regulate BLM sumoylation","family":"Belongs to the RanBP2 E3 ligase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10078529","11792325","12032081","15378033","15931224","20386726","20676357","22155184","22194619","22902403","23353830","7775481"],"location":"Nucleus；Nucleus membrane；Nucleus, nuclear pore complex；Nucleus envelope","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；细胞周期/分裂；注释原文：E3 SUMO-protein ligase which facilitates SUMO1 and SUMO2 conjugation by UBE2I (PubMed:11792325, PubMed:12032081, PubMed:15378033, PubMed:15931224, PubMed:22194619).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"核质运输；细胞周期/分裂"},"RANBP3":{"hgnc":"HGNC:9850","symbol":"RANBP3","accessions":["Q9H6Z4"],"name":"Ran-binding protein 3","length":"567","function":"Acts as a cofactor for XPO1/CRM1-mediated nuclear export, perhaps as export complex scaffolding protein. Bound to XPO1/CRM1, stabilizes the XPO1/CRM1-cargo interaction. In the absence of Ran-bound GTP prevents binding of XPO1/CRM1 to the nuclear pore complex. Binds to CHC1/RCC1 and increases the guanine nucleotide exchange activity of CHC1/RCC1. Recruits XPO1/CRM1 to CHC1/RCC1 in a Ran-dependent manner. Negative regulator of TGF-beta signaling through interaction with the R-SMAD proteins, SMAD2 and SMAD3, and mediating their nuclear export","subunit":"Interacts with CHC1 in a Ran-stimulated manner. Interacts with XPO1. Interacts (via its C-terminal R domain) with SMAD2 (dephosphorylated form via its MH1 and MH2 domains); the interaction results in the nuclear export of SMAD2 and termination of the TGF-beta signaling. Interacts (via its C-terminal R domain) with SMAD3 (dephosphorylated form via its MH1 domain); the interaction results in the nuclear export of SMAD3 and termination of the TGF-beta signaling","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11425870","11571268","11932251","19289081","9637251"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；注释原文：Acts as a cofactor for XPO1/CRM1-mediated nuclear export, perhaps as export complex scaffolding protein.","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输"},"RANBP9":{"hgnc":"HGNC:13727","symbol":"RANBP9","accessions":["Q96S59"],"name":"Ran-binding protein 9","length":"729","function":"May act as scaffolding protein, and as adapter protein to couple membrane receptors to intracellular signaling pathways (Probable). Acts as a mediator of cell spreading and actin cytoskeleton rearrangement (PubMed:18710924). Core component of the CTLH E3 ubiquitin-protein ligase complex that selectively accepts ubiquitin from UBE2H and mediates ubiquitination and subsequent proteasomal degradation of the transcription factor HBP1 (PubMed:29911972). May be involved in signaling of ITGB2/LFA-1 and other integrins (PubMed:14722085). Enhances HGF-MET signaling by recruiting Sos and activating the Ras pathway (PubMed:12147692). Enhances dihydrotestosterone-induced transactivation activity of AR, as well as dexamethasone-induced transactivation activity of NR3C1, but not affect estrogen-induced transactivation (PubMed:12361945, PubMed:18222118). Stabilizes TP73 isoform Alpha, probably by inhibiting its ubiquitination, and increases its proapoptotic activity (PubMed:15558019). Inhibits the kinase activity of DYRK1A and DYRK1B. Inhibits FMR1 binding to RNA","subunit":"Part of a complex consisting of RANBP9, MKLN1 and GID8 (PubMed:12559565). Identified in the CTLH complex that contains GID4, RANBP9 and/or RANBP10, MKLN1, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, ARMC8, WDR26 and YPEL5 (PubMed:17467196, PubMed:29911972). Within this complex, MAEA, RMND5A (or alternatively its paralog RMND5B), GID8, WDR26, and RANBP9 and/or RANBP10 form the catalytic core, while GID4, MKLN1, ARMC8 and YPEL5 have ancillary roles (PubMed:29911972). Interacts with GTP-bound Ran, AR, CDC2L1/p110C, CALB1, S100A7, USP11, MKLN1, SOS1 or SOS2, GID8, and FMR1 (PubMed:11470507, PubMed:12084015, PubMed:12147692, PubMed:12361945, PubMed:12421467, PubMed:12684061, PubMed:14511641, PubMed:14684163, PubMed:15381419, PubMed:18710924, PubMed:9817760). Interacts with the Dyrk kinases HIPK2, DYRK1A, and DYRK1B (PubMed:12220523, PubMed:14500717). Interacts with TP73 isoform Alpha but not with TP53 (PubMed:15558019). Interacts with the HGF receptor MET and the integrins ITGB1 and ITGB2, but not with ITGAL (PubMed:14722085). Part of a complex consisting of RANBP9, RAN, DYRK1B and COPS5 (PubMed:14500717). Directly interacts with RANBP10 (PubMed:18222118). Interacts with YPEL5 (PubMed:20580816). Interacts with DDX4 (PubMed:27622290). Interacts with NGFR (By similarity). Interacts with TEX19 (By similarity)","family":"Belongs to the RANBP9/10 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12147692","12361945","14500717","14722085","15381419","15558019","18222118","18710924","29911972"],"location":"Cytoplasm；Nucleus；Cell membrane；Peripheral membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：May act as scaffolding protein, and as adapter protein to couple membrane receptors to intracellular signaling pathways (Probable).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面"},"RANGAP1":{"hgnc":"HGNC:9854","symbol":"RANGAP1","accessions":["P46060"],"name":"Ran GTPase-activating protein 1","length":"587","function":"GTPase activator for RAN (PubMed:16428860, PubMed:8146159, PubMed:8896452). Converts cytoplasmic GTP-bound RAN to GDP-bound RAN, which is essential for RAN-mediated nuclear import and export (PubMed:27160050, PubMed:8896452). Mediates dissociation of cargo from nuclear export complexes containing XPO1, RAN and RANBP2 after nuclear export (PubMed:27160050)","subunit":"Homodimer (PubMed:8146159). Interacts with RAN (PubMed:16428860, PubMed:7891706, PubMed:8896452). Forms a complex with RANBP2/NUP358, NXF1 and NXT1 (PubMed:14729961). Forms a tight complex in association with RANBP2/NUP358 and UBE2I/UBC9, the ubiquitin-conjugating enzyme E2 (PubMed:15037602, PubMed:15931224, PubMed:22194619, PubMed:27160050). Interacts with UBE2I; the interaction conjugates SUMO1 to RANGAP1, and subsequently stabilizes interactions of sumoylated RANGAP1 with RANBP2/NUP358 (PubMed:15037602, PubMed:15931224, PubMed:27160050). The complex composed of RANBP2, SUMO1, RANGAP1 and UBE2I associates with nuclear pore complexes (PubMed:15037602, PubMed:15931224). Identified in a complex composed of RAN, RANBP2, sumoylated RANGAP1, UBE2I and XPO1 (PubMed:27160050). Identified in a complex composed of RAN, RANGAP1 and RANBP1 (PubMed:16428860). Interacts with TRAF6 (PubMed:18093978). Interacts with SUMO1 and SENP1 (PubMed:17099698). Interacts (when sumoylated) with MYCBP2; interaction inhibits MYCBP2 E3 ubiquitin-protein ligase activity and promotes MYCBP2 translocation to the nucleus (PubMed:26304119)","family":"Belongs to the RNA1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16428860","27160050","8146159","8896452"],"location":"Cytoplasm；Nucleus, nucleoplasm；Nucleus envelope；Chromosome, centromere, kinetochore；Cytoplasm, cytoskeleton, spindle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；注释原文：GTPase activator for RAN (PubMed:16428860, PubMed:8146159, PubMed:8896452).","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输"},"RANGRF":{"hgnc":"HGNC:17679","symbol":"RANGRF","accessions":["Q9HD47"],"name":"Ran guanine nucleotide release factor","length":"186","function":"May regulate the intracellular trafficking of RAN (PubMed:11290418). Promotes guanine nucleotide release from RAN and inhibits binding of new GTP by preventing the binding of the RAN guanine nucleotide exchange factor RCC1 (PubMed:29040603). Regulates the levels of GTP-bound RAN in the nucleus, and thereby plays a role in the regulation of RAN-dependent mitotic spindle dynamics (PubMed:29040603). Enhances the expression of SCN5A at the cell membrane in cardiomyocytes (PubMed:18184654, PubMed:21621375, PubMed:23420830)","subunit":"Monomer. Interacts with RAN, both RAN-GTP and RAN-GDP (PubMed:11290418, PubMed:29040603). Competes with RCC1 for a common binding site on RAN and thereby inhibits RCC1-mediated nucleotide exchange (PubMed:29040603). Forms a complex with RAN-GTP and RANBP1 (By similarity). Interacts with the cytoplasmic loop 2 of SCN5A (PubMed:18184654)","family":"Belongs to the MOG1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11290418","18184654","21621375","23420830","29040603"],"location":"Nucleus；Cytoplasm, perinuclear region；Cytoplasm；Cell membrane；Peripheral membrane protein；Cytoplasmic side","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；注释原文：May regulate the intracellular trafficking of RAN (PubMed:11290418).","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞周期/分裂"},"RAP1GDS1":{"hgnc":"HGNC:9859","symbol":"RAP1GDS1","accessions":["P52306"],"name":"Rap1 GTPase-GDP dissociation stimulator 1","length":"607","function":"Acts as a GEF (guanine nucleotide exchange factor) for the Rho family of small GTP-binding proteins (G proteins) that stimulates the dissociation of GDP to enable subsequent binding of GTP (PubMed:11948427, PubMed:1549351, PubMed:20709748, PubMed:28630045, PubMed:30190425). Additionally, appears to chaperone the processing and/or trafficking of small GTPases containing a C-terminal polybasic region independently of GEF activity (PubMed:20709748, PubMed:21242305). Targets include RAP1A/RAP1B, RHOA, RHOB, RHOC, RAC1 and KRAS (PubMed:11948427, PubMed:1549351, PubMed:20709748, PubMed:24415755). Regulates mitochondrial dynamics by controlling RHOT function to promote mitochondrial fission during high calcium conditions (PubMed:27716788). Able to promote the Ca(2+) release from the endoplasmic reticulum via both inositol trisphosphate (Ins3P) and ryanodine sensitive receptors leading to a enhanced mitochondrial Ca(2+) uptake (PubMed:24349085)\nActs as a GEF (guanine nucleotide exchange factor) for unprenylated RHOA (PubMed:24415755, PubMed:28630045, PubMed:30190425). Chaperones the entry and passage of small GTPases through the prenylation pathway (PubMed:20709748). Recognizes the last amino acid in the GTPase C-terminal CAAX motif with a preference for 'Leu' over 'Met', indicating involvement in the geranylgeranylation pathway (PubMed:24415755)\nActs as a GEF (guanine nucleotide exchange factor) for prenylated RHOA (PubMed:21242305, PubMed:28630045, PubMed:30190425). Acts as a GEF for RHOC (PubMed:21242305). Chaperones the downstream trafficking and/or processing of small newly prenylated GTPases (PubMed:20709748). Escorts RAC1 to the nucleus (PubMed:12551911)","subunit":"Interacts with RABL3 (PubMed:31406347). Interacts with RHOT1 (PubMed:27716788)\nInteracts with unprenylated RHOA; the interaction is direct (PubMed:20709748, PubMed:28630045, PubMed:30190425). Interacts with RAP1A (PubMed:20709748). Interacts with KRAS (PubMed:20709748, PubMed:24415755). Interacts with RAC1 (PubMed:20709748). Interacts with RAP1B (PubMed:24415755). Preferentially interacts with unprenylated GTPases that will become geranylgeranylated (PubMed:24415755). May also interact with prenylated GTPases (PubMed:24415755)\nInteracts with prenylated RHOA; the interaction is direct and in a 1:1 stoichiometry (PubMed:12551911, PubMed:20709748, PubMed:28630045, PubMed:30190425). Interacts with RAP1A (PubMed:20709748). Interacts with KRAS (PubMed:20709748, PubMed:24415755). Interacts with RAC1 (PubMed:12551911, PubMed:20709748). Interacts with RAP1B (PubMed:24415755). Preferentially interacts with prenylated GTPases (PubMed:24415755)","family":"","domains":[],"function_pmids":["11948427","12551911","1549351","20709748","21242305","24349085","24415755","27716788","28630045","30190425"],"location":"Cytoplasm, cytosol; Endoplasmic reticulum; Mitochondrion; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a GEF (guanine nucleotide exchange factor) for the Rho family of small GTP-binding proteins (G proteins) that stimulates the dissociation of GDP to enable subsequent binding of GTP (PubMed:11948427, PubMed:1549351, PubMed:20709748, PubMed:28630045, PubMed:30190425). Additionally, appears to chaperone the processing and/or trafficking of small GTPases containing a C-terminal polybasic region independently of GEF activity (PubMed:20709748, PubMed:21242305). Targets include RAP1A/RAP1B, RHOA, RHOB, RHOC, RAC1 and KRAS (PubMed:11948427, PubMed:1549351, PubMed:20709748, PubMed:24415755). Regulates mitochondrial dynamics by controlling RHOT function to promote mitochondrial fission during high calcium conditions (PubMed:27716788). Able to promote the Ca(2+) release from the endoplasmic reticulum via both inositol trisphosphate (Ins3P) and ryanodine sensitive receptors leading to a enhanced mitochondrial Ca(2+) uptake (PubMed:24349085)\nActs as a GEF (guanine nucleotide exchange factor) for unprenylated RHOA (PubMed:24415755, PubMed:28630045, PubMed:30190425). Chaperones the entry and passage of small GTPases through the prenylation pathway (PubMed:20709748). Recognizes the last amino acid in the GTPase C-terminal CAAX motif with a preference for 'Leu' over 'Met', indicating involvement in the geranylgeranylation pathway (PubMed:24415755)\nActs as a GEF (guanine nucleotide exchange factor) for prenylated RHOA (PubMed:21242305, PubMed:28630045, PubMed:30190425). Acts as a GEF for RHOC (PubMed:21242305). Chaperones the downstream trafficking and/or processing of small newly prenylated GTPases (PubMed:20709748). Escorts RAC1 to the nucleus (PubMed:12551911)"},"RARG":{"hgnc":"HGNC:9866","symbol":"RARG","accessions":["P13631"],"name":"Retinoic acid receptor gamma","length":"454","function":"Receptor for retinoic acid. Retinoic acid receptors bind as heterodimers to their target response elements in response to their ligands, all-trans or 9-cis retinoic acid, and regulate gene expression in various biological processes. The RAR/RXR heterodimers bind to the retinoic acid response elements (RARE) composed of tandem 5'-AGGTCA-3' sites known as DR1-DR5. In the absence of ligand, acts mainly as an activator of gene expression due to weak binding to corepressors. Required for limb bud development. In concert with RARA or RARB, required for skeletal growth, matrix homeostasis and growth plate function (By similarity)","subunit":"Homodimer. Heterodimer with a RXR molecule. Binds DNA preferentially as a RAR/RXR heterodimer. Forms a complex with PUS1 and the SRA1 RNA in the nucleus","family":"Belongs to the nuclear hormone receptor family. NR1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；发育/分化；注释原文：Receptor for retinoic acid.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"黏附/受体/细胞表面；发育/分化"},"RARS1":{"hgnc":"HGNC:9870","symbol":"RARS1","accessions":["P54136"],"name":"Arginine--tRNA ligase, cytoplasmic","length":"660","function":"Forms part of a macromolecular complex that catalyzes the attachment of specific amino acids to cognate tRNAs during protein synthesis (PubMed:25288775). Modulates the secretion of AIMP1 and may be involved in generation of the inflammatory cytokine EMAP2 from AIMP1 (PubMed:17443684)","subunit":"Interacts (via N-terminus) with AIMP1 (via N-terminus); this stimulates its catalytic activity (PubMed:10358004, PubMed:25288775). Interacts (via N-terminus) with LARS2 (via C-terminus) (PubMed:16055448, PubMed:17443684). Monomer (PubMed:24859084). Part of a multisubunit complex that groups tRNA ligases for Arg (RARS1), Asp (DARS1), Gln (QARS1), Ile (IARS1), Leu (LARS1), Lys (KARS1), Met (MARS1) the bifunctional ligase for Glu and Pro (EPRS1) and the auxiliary subunits AIMP1/p43, AIMP2/p38 and EEF1E1/p18 (PubMed:19131329, PubMed:19289464). Interacts with QARS1 (PubMed:24656866). Part of a complex composed of RARS1, QARS1 and AIMP1 (PubMed:25288775)","family":"Belongs to the class-I aminoacyl-tRNA synthetase family","domains":[],"function_pmids":["17443684","25288775"],"location":"Cytoplasm; Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Forms part of a macromolecular complex that catalyzes the attachment of specific amino acids to cognate tRNAs during protein synthesis (PubMed:25288775). Modulates the secretion of AIMP1 and may be involved in generation of the inflammatory cytokine EMAP2 from AIMP1 (PubMed:17443684)"},"RASSF1":{"hgnc":"HGNC:9882","symbol":"RASSF1","accessions":["Q9NS23"],"name":"Ras association domain-containing protein 1","length":"344","function":"Potential tumor suppressor. Required for death receptor-dependent apoptosis. Mediates activation of STK3/MST2 and STK4/MST1 during Fas-induced apoptosis by preventing their dephosphorylation. When associated with MOAP1, promotes BAX conformational change and translocation to mitochondrial membranes in response to TNF and TNFSF10 stimulation. Isoform A interacts with CDC20, an activator of the anaphase-promoting complex, APC, resulting in the inhibition of APC activity and mitotic progression. Inhibits proliferation by negatively regulating cell cycle progression at the level of G1/S-phase transition by regulating accumulation of cyclin D1 protein. Isoform C has been shown not to perform these roles, no function has been identified for this isoform. Isoform A disrupts interactions among MDM2, DAXX and USP7, thus contributing to the efficient activation of TP53 by promoting MDM2 self-ubiquitination in cell-cycle checkpoint control in response to DNA damage","subunit":"Interacts with MAP1S (PubMed:15205320, PubMed:15753381). Interacts with XPA (PubMed:10888881). Binds to the N-terminal of CDC20 during prometaphase (PubMed:14743218). Binds to STK3/MST2 and STK4/MST1 (PubMed:15109305, PubMed:16510573, PubMed:21199877). Recruited to the TNFRSF1A and TNFRSF10A complexes in response to their respective cognate ligand, after internalization (PubMed:15949439). Can self-associate (PubMed:11857081). Part of a complex with MDM2, DAXX, RASSF1 and USP7 (PubMed:18566590). Interacts with ECM2 (By similarity)\nInteracts with MOAP1 (PubMed:15949439). Interacts with E4F1 (PubMed:14729613). Interacts with RSSF5 and probably associates with HRAS via a RSSF1 isoform A-RSSF5 heterodimer (PubMed:11857081). Interacts (via C-terminus) with DAXX (via N-terminus); the interaction is independent of MDM2 and TP53 (PubMed:18566590). Interacts (via N-terminus) with MDM2 (via C-terminus); the interaction is independent of TP53 (PubMed:18566590). Interacts with RAB39A (By similarity). Interacts with RAB39B; the interaction is weak (By similarity)\nInteracts (via N-terminus) with DAXX (PubMed:18566590). Interacts with RAB39B; the interaction is strong (By similarity). Does not interact with RAB39A (By similarity)\nInteracts (via N-terminus) with DAXX","family":"","domains":[],"function_pmids":["10888881","11333291","12024041","14743218","15109305","15949439","16510573","18566590","21199877"],"location":"Cytoplasm, cytoskeleton; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle; Cytoplasm, cytoskeleton, spindle pole; Nucleus; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Potential tumor suppressor. Required for death receptor-dependent apoptosis. Mediates activation of STK3/MST2 and STK4/MST1 during Fas-induced apoptosis by preventing their dephosphorylation. When associated with MOAP1, promotes BAX conformational change and translocation to mitochondrial membranes in response to TNF and TNFSF10 stimulation. Isoform A interacts with CDC20, an activator of the anaphase-promoting complex, APC, resulting in the inhibition of APC activity and mitotic progression. Inhibits proliferation by negatively regulating cell cycle progression at the level of G1/S-phase transition by regulating accumulation of cyclin D1 protein. Isoform C has been shown not to perform these roles, no function has been identified for this isoform. Isoform A disrupts interactions among MDM2, DAXX and USP7, thus contributing to the efficient activation of TP53 by promoting MDM2 self-ubiquitination in cell-cycle checkpoint control in response to DNA damage"},"RASSF6":{"hgnc":"HGNC:20796","symbol":"RASSF6","accessions":["Q6ZTQ3"],"name":"Ras association domain-containing protein 6","length":"369","function":"Involved in the induction of apoptosis, through both caspase-dependent and caspase-independent pathways. May act as a Ras effector protein. May suppress the serum-induced basal levels of NF-kappa-B (By similarity)","subunit":"Interacts with MOAP1 (By similarity). Interaction with activated KRAS is still a matter of debate: interaction has been shown in the mouse (PubMed:17404571), but not in human (PubMed:17367779). Lack of interaction with MRAS, NRAS nor RRAS2 has also been reported (PubMed:17367779)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17367779"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"免疫/炎症/细胞死亡；注释原文：Involved in the induction of apoptosis, through both caspase-dependent and caspase-independent pathways.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"免疫/炎症/细胞死亡"},"RAVER1":{"hgnc":"HGNC:30296","symbol":"RAVER1","accessions":["Q8IY67"],"name":"Ribonucleoprotein PTB-binding 1","length":"606","function":"Cooperates with PTBP1 to modulate regulated alternative splicing events. Promotes exon skipping. Cooperates with PTBP1 to modulate switching between mutually exclusive exons during maturation of the TPM1 pre-mRNA (By similarity)","subunit":"Interacts with PTBP1, RAVER2, VCL and ACTN1. Part of a complex containing RAVER1, VCL and ACTN1 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Cooperates with PTBP1 to modulate regulated alternative splicing events.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接"},"RB1":{"hgnc":"HGNC:9884","symbol":"RB1","accessions":["P06400"],"name":"Retinoblastoma-associated protein","length":"928","function":"Tumor suppressor that is a key regulator of the G1/S transition of the cell cycle (PubMed:10499802). The hypophosphorylated form binds transcription regulators of the E2F family, preventing transcription of E2F-responsive genes (PubMed:10499802). Both physically blocks E2Fs transactivating domain and recruits chromatin-modifying enzymes that actively repress transcription (PubMed:10499802). Cyclin and CDK-dependent phosphorylation of RB1 induces its dissociation from E2Fs, thereby activating transcription of E2F responsive genes and triggering entry into S phase (PubMed:10499802). RB1 also promotes the G0-G1 transition upon phosphorylation and activation by CDK3/cyclin-C (PubMed:15084261). Directly involved in heterochromatin formation by maintaining overall chromatin structure and, in particular, that of constitutive heterochromatin by stabilizing histone methylation. Recruits and targets histone methyltransferases SUV39H1, KMT5B and KMT5C, leading to epigenetic transcriptional repression. Controls histone H4 'Lys-20' trimethylation. Inhibits the intrinsic kinase activity of TAF1. Mediates transcriptional repression by SMARCA4/BRG1 by recruiting a histone deacetylase (HDAC) complex to the c-FOS promoter. In resting neurons, transcription of the c-FOS promoter is inhibited by BRG1-dependent recruitment of a phospho-RB1-HDAC1 repressor complex. Upon calcium influx, RB1 is dephosphorylated by calcineurin, which leads to release of the repressor complex (By similarity)\n(Microbial infection) In case of viral infections, interactions with SV40 large T antigen, HPV E7 protein or adenovirus E1A protein induce the disassembly of RB1-E2F1 complex thereby disrupting RB1's activity","subunit":"The hypophosphorylated form interacts with and sequesters the E2F1 transcription factor, thereby inhibiting E2F1 transcription (PubMed:20940255, PubMed:8336704). Interacts with heterodimeric E2F/DP transcription factor complexes containing TFDP1 and either E2F1, E2F3, E2F4 or E2F5, or TFDP2 and E2F4. Interacts (when hyperphosphorylated and hypophosphorylated) with PKP3; the interaction inhibits RB1 interaction with and repression of the transcription factor E2F1, potentially via sequestering RB1 to the cytoplasm (By similarity). The unphosphorylated form interacts with EID1, ARID3B, KDM5A, SUV39H1, MJD2A/JHDM3A and THOC1. Interacts with the N-terminal domain of TAF1. Interacts with SNW1, ATAD5, AATF, DNMT1, LIN9, LMNA, KMT5B, KMT5C, PELP1, UHRF2 and TMPO-alpha. Interacts with GRIP1 and UBR4. Interacts with ARID4A and KDM5B. Interacts with E4F1 and LIMD1. Interacts with SMARCA4/BRG1 and HDAC1 (By similarity). Interacts with PSMA3 and USP4. Interacts (when methylated at Lys-860) with L3MBTL1. Interacts with CHEK2; phosphorylates RB1. Interacts with CDK1 and CDK2 (By similarity). Interacts with PRMT2. Interacts with CEBPA (PubMed:15107404). P-TEFB complex interacts with RB1; promotes phosphorylation of RB1 (PubMed:12037672). Interacts with RBBP9; the interaction disrupts RB1 binding to E2F1 (By similarity). Interacts with KAT2B/PCAF and EP300/P300 (By similarity). Interacts with PAX5 (PubMed:10197586). Interacts (phosphorylated and unphosphorylated) with BLCAP (PubMed:26986503). May interact with NDC80\n(Microbial infection) Interacts with adenovirus E1A protein\n(Microbial infection) Interacts with HPV E7 protein\n(Microbial infection) Interacts with SV40 large T antigen\n(Microbial infection) Interacts with human cytomegalovirus/HHV-5 proteins UL82 and UL123\n(Microbial infection) Interacts with molluscum contagiosum virus protein MC007","family":"Belongs to the retinoblastoma protein (RB) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10499802","1316611","15084261","17974914","18701596","2839300","8892909"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；注释原文：Tumor suppressor that is a key regulator of the G1/S transition of the cell cycle (PubMed:10499802).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号"},"RB1CC1":{"hgnc":"HGNC:15574","symbol":"RB1CC1","accessions":["Q8TDY2"],"name":"RB1-inducible coiled-coil protein 1","length":"1594","function":"Involved in autophagy (PubMed:21775823). Regulates early events but also late events of autophagosome formation through direct interaction with Atg16L1 (PubMed:23392225). Required for the formation of the autophagosome-like double-membrane structure that surrounds the Salmonella-containing vacuole (SCV) during S.typhimurium infection and subsequent xenophagy (By similarity). Involved in repair of DNA damage caused by ionizing radiation, which subsequently improves cell survival by decreasing apoptosis (By similarity). Inhibits PTK2/FAK1 and PTK2B/PYK2 kinase activity, affecting their downstream signaling pathways (PubMed:10769033, PubMed:12221124). Plays a role as a modulator of TGF-beta-signaling by restricting substrate specificity of RNF111 (By similarity). Functions as a DNA-binding transcription factor (PubMed:12095676). Is a potent regulator of the RB1 pathway through induction of RB1 expression (PubMed:14533007). Plays a crucial role in muscular differentiation (PubMed:12163359). Plays an indispensable role in fetal hematopoiesis and in the regulation of neuronal homeostasis (By similarity)","subunit":"Part of a complex consisting of ATG13/KIAA0652, ULK1 and RB1CC1 (PubMed:19211835, PubMed:19597335). This complex associates with ATG101 (PubMed:19211835, PubMed:19597335). Interacts with PTK2/FAK1 and PTK2B/PYK2 (PubMed:10769033, PubMed:12221124). Interacts with GABARAP and GABARAPL1 (PubMed:23043107). Interacts with ATG16L1; the interaction is required for ULK1 complex-dependent autophagy (PubMed:23262492, PubMed:23392225, PubMed:24954904, PubMed:28890335). Interacts with RNF111, SKI and SMAD7 (By similarity). Interacts with COP1 in the cytoplasm of proliferating cells in response to UV stimulation (PubMed:23289756). Interacts with TP53 (PubMed:21775823). Interacts with C9orf72 (PubMed:27334615). Interacts with WDR45B (PubMed:28561066). Interacts with ATG13; this interaction is increased in the absence of TMEM39A (PubMed:31806350). Interacts with WIPI2 (PubMed:28890335). Interacts with TAX1BP1 (PubMed:33226137, PubMed:34471133). Interacts (via phosphorylated FFAT motif) with MOSPD2, VAPA and VAPB (PubMed:33124732)","family":"Belongs to the ATG17 family","domains":[],"function_pmids":["10769033","12095676","12163359","12221124","14533007","21775823","23392225"],"location":"Nucleus; Cytoplasm; Cytoplasm, cytosol; Preautophagosomal structure; Lysosome","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in autophagy (PubMed:21775823). Regulates early events but also late events of autophagosome formation through direct interaction with Atg16L1 (PubMed:23392225). Required for the formation of the autophagosome-like double-membrane structure that surrounds the Salmonella-containing vacuole (SCV) during S.typhimurium infection and subsequent xenophagy (By similarity). Involved in repair of DNA damage caused by ionizing radiation, which subsequently improves cell survival by decreasing apoptosis (By similarity). Inhibits PTK2/FAK1 and PTK2B/PYK2 kinase activity, affecting their downstream signaling pathways (PubMed:10769033, PubMed:12221124). Plays a role as a modulator of TGF-beta-signaling by restricting substrate specificity of RNF111 (By similarity). Functions as a DNA-binding transcription factor (PubMed:12095676). Is a potent regulator of the RB1 pathway through induction of RB1 expression (PubMed:14533007). Plays a crucial role in muscular differentiation (PubMed:12163359). Plays an indispensable role in fetal hematopoiesis and in the regulation of neuronal homeostasis (By similarity)"},"RBAK":{"hgnc":"HGNC:17680","symbol":"RBAK","accessions":["Q9NYW8"],"name":"RB-associated KRAB zinc finger protein","length":"714","function":"May repress E2F-dependent transcription. May promote AR-dependent transcription","subunit":"Interacts with AR and RB1. May also interact with other nuclear hormone receptors such as NR3C1/GR","family":"Belongs to the krueppel C2H2-type zinc-finger protein family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10702291","14664718"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May repress E2F-dependent transcription.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"RBBP4":{"hgnc":"HGNC:9887","symbol":"RBBP4","accessions":["Q09028"],"name":"Histone-binding protein RBBP4","length":"425","function":"Core histone-binding subunit that may target chromatin assembly factors, chromatin remodeling factors and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA (PubMed:10866654). Component of the chromatin assembly factor 1 (CAF-1) complex, which is required for chromatin assembly following DNA replication and DNA repair (PubMed:8858152). Component of the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression (PubMed:9150135). Component of the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling (PubMed:16428440, PubMed:28977666, PubMed:39460621). Component of the PRC2 complex, which promotes repression of homeotic genes during development (PubMed:29499137, PubMed:31959557). Component of the NURF (nucleosome remodeling factor) complex (PubMed:14609955, PubMed:15310751)","subunit":"Binds directly to helix 1 of the histone fold of histone H4, a region that is not accessible when H4 is in chromatin (PubMed:24920672, PubMed:8858152, PubMed:9427644). Subunit of the chromatin assembly factor 1 (CAF-1) complex, which is composed of RBBP4, CHAF1B and CHAF1A (PubMed:8858152). Subunit of the core histone deacetylase (HDAC) complex, which is composed of HDAC1, HDAC2, RBBP4 and RBBP7 (PubMed:9150135). The core HDAC complex associates with SIN3A, ARID4B/SAP180, SAP18, SAP30, SAP130, SUDS3/SAP45 and possibly ARID4A/RBP1 and ING1 to form the SIN3 HDAC complex (PubMed:11118440, PubMed:11784859, PubMed:9150135, PubMed:9651585). Component of the nucleosome remodeling and deacetylase (NuRD) repressor complex, composed of core proteins MTA1, MTA2, MTA3, RBBP4, RBBP7, HDAC1, HDAC2, MBD2, MBD3, and peripherally associated proteins CDK2AP1, CDK2AP2, GATAD2A, GATAD2B, CHD3, CHD4 and CHD5 (PubMed:10444591, PubMed:11102443, PubMed:16428440, PubMed:28977666, PubMed:33283408, PubMed:9790534, PubMed:39460621). The exact stoichiometry of the NuRD complex is unknown, and some subunits such as MBD2 and MBD3, GATAD2A and GATAD2B, and CHD3, CHD4 and CHD5 define mutually exclusive NuRD complexes (PubMed:16428440, PubMed:28977666, PubMed:33283408). Interacts with ZNF512B; the interaction is direct and may play a role in repressing gene expression (PubMed:39460621). The NuRD complex may also interact with MBD3L1 and MBD3L2 (PubMed:15456747, PubMed:15701600). Component of the PRC2 complex, which consists of the core subunits EED, EZH1 or EZH2, SUZ12, and RBBP4, and various combinations of accessory subunits including AEBP2, JARID2, PHF19, MTF2 and EPOP (PubMed:12351676, PubMed:12435631, PubMed:29499137, PubMed:31959557). Forms a monomeric PRC2.2 (class 2) complex consisting of at least SUZ12, RBBP4, AEBP2 and JARID2 (PubMed:29499137). Forms a dimeric PRC2.1 (class 1, PRC-PCL) complex consisting of at least SUZ12, RBBP4, and PHF19; PHF19 stabilizes the dimeric structure which enhances PRC2 interaction with chromatin (PubMed:31959557). Component of the NURF-1 ISWI chromatin remodeling complex (also called the nucleosome-remodeling factor (NURF) complex) at least composed of SMARCA1 (isoform 2), BPTF, RBBP4 and RBBP7 (PubMed:14609955, PubMed:15310751). Within the complex interacts with isoform 2 of SMARCA1 (PubMed:14609955, PubMed:15310751). Component of the BPFT-SMARCA1 complex at least composed of SMARCA1 (isoform 1), BPFT, RBBP4 and RBBP7; the complex is catalytically inactive and does not remodel chromatin (PubMed:15310751). Within the complex interacts with isoform 1 of SMARCA1 (PubMed:15310751). Interacts with the ISWI chromatin remodeling complex component SMARCA5; the interaction is direct (PubMed:12198550). Interacts with the viral protein-binding domain of the retinoblastoma protein (RB1) (PubMed:10734134, PubMed:7503932). Component of the DREAM complex (also named LINC complex) at least composed of E2F4, E2F5, LIN9, LIN37, LIN52, LIN54, MYBL1, MYBL2, RBL1, RBL2, RBBP4, TFDP1 and TFDP2 (PubMed:17531812, PubMed:17671431). The complex exists in quiescent cells where it represses cell cycle-dependent genes (PubMed:17531812, PubMed:17671431). It dissociates in S phase when LIN9, LIN37, LIN52 and LIN54 form a subcomplex that binds to MYBL2 (PubMed:17531812, PubMed:17671431). Found in a complex composed of at least SINHCAF, SIN3A, HDAC1, SAP30, RBBP4, OGT and TET1 (By similarity). Interacts with ZNF827; the interaction is direct and recruits RBBP4 to telomeres (PubMed:30045876). Interacts with MTA1; the interaction is direct and mutually exclusive with binding histone H4 (PubMed:12920132, PubMed:24920672). Interacts with ARMC12 (via ARM domains) (PubMed:30026490). Interacts with BRCA1 (PubMed:10220405). Interacts with CDK2AP1 (PubMed:20523938). Interacts with CREBBP, and this interaction may be enhanced by the binding of phosphorylated CREB1 to CREBBP (PubMed:10866654). Interacts with ERCC6 (PubMed:26030138). Interacts with HDAC7 (By similarity). Interacts with PHF6 (PubMed:24554700). Interacts with PWWP2B (By similarity). Interacts with SPEN/MINT (PubMed:11331609). Interacts with SUV39H1 (By similarity). Interacts with MECOM and PRDM16 (PubMed:30462309)","family":"Belongs to the WD repeat RBAP46/RBAP48/MSI1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10866654","14609955","15310751","16428440","28977666","29499137","31959557","39460621","8858152","9150135"],"location":"Nucleus；Chromosome, telomere","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；发育/分化；注释原文：Core histone-binding subunit that may target chromatin assembly factors, chromatin remodeling factors and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA (PubMed:10866654).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；发育/分化"},"RBBP5":{"hgnc":"HGNC:9888","symbol":"RBBP5","accessions":["Q15291"],"name":"Retinoblastoma-binding protein 5","length":"538","function":"In embryonic stem (ES) cells, plays a crucial role in the differentiation potential, particularly along the neural lineage, regulating gene induction and H3 'Lys-4' methylation at key developmental loci, including that mediated by retinoic acid (By similarity). Does not affect ES cell self-renewal (By similarity). Component or associated component of some histone methyltransferase complexes which regulates transcription through recruitment of those complexes to gene promoters (PubMed:19131338). As part of the MLL1/MLL complex, involved in mono-, di- and trimethylation at 'Lys-4' of histone H3 (PubMed:19556245). Histone H3 'Lys-4' methylation represents a specific tag for epigenetic transcriptional activation (PubMed:19556245). In association with ASH2L and WDR5, stimulates the histone methyltransferase activities of KMT2A, KMT2B, KMT2C, KMT2D, SETD1A and SETD1B (PubMed:21220120, PubMed:22266653)","subunit":"Component of the SET1 complex, at least composed of the catalytic subunit (SETD1A or SETD1B), WDR5, WDR82, RBBP5, ASH2L/ASH2, CXXC1/CFP1, HCFC1 and DPY30 (PubMed:16253997, PubMed:17355966, PubMed:17998332, PubMed:18838538). Core component of several methyltransferase-containing complexes including MLL1/MLL, MLL2/3 (also named ASCOM complex) and MLL4/WBP7 (PubMed:15199122, PubMed:15960975, PubMed:17500065). Each complex is at least composed of ASH2L, RBBP5, WDR5, DPY30, one or more specific histone methyltransferases (KMT2A/MLL1, KMT2D/MLL2, KMT2C/MLL3 and KMT2B/MLL4), and the facultative components PAGR1, BACC1, CHD8, E2F6, HCFC1, HCFC2, HSP70, INO80C, KDM6A, KANSL1, LAS1L, MAX, MCRS1, MEN1, MGA, MYST1/MOF, NCOA6, PAXIP1/PTIP, PELP1, PHF20, PRP31, RING2, RUVB1/TIP49A, RUVB2/TIP49B, SENP3, TAF1, TAF4, TAF6, TAF7, TAF9, TEX10 and alpha- and beta-tubulin (PubMed:14992727, PubMed:15199122, PubMed:15960975, PubMed:17500065). Component of a histone methylation complex composed of at least ZNF335, RBBP5, ASH2L and WDR5; the complex may have histone H3-specific methyltransferase activity, however does not have specificity for 'Lys-4' of histone H3 (PubMed:19131338). Interacts with ZNF335 (PubMed:19131338, PubMed:23178126). Interacts with ASH2L; the interaction is direct (PubMed:19131338, PubMed:19556245, PubMed:21220120). Interacts with WDR5; the interaction is direct (PubMed:19556245, PubMed:21220120). Components of the ZNF335-RBBP5-ASH2L-WDR5 histone methylation complex may associate with components of a nuclear receptor-mediated transcription complex to form a complex at least composed of ZNF335, HCFC1, CCAR2, EMSY, MKI67, RBBP5, ASH2L and WDR5 (PubMed:19131338). Within this complex interacts with EMSY (PubMed:19131338). Found in a complex with RBBP5, ASH2L, DPY30, KMT2A, KMT2D and WDR5 (By similarity). Interacts with SETD1A (PubMed:17998332). Interacts with WDR82 (PubMed:18838538)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19131338","19556245","21220120","22266653"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：In embryonic stem (ES) cells, plays a crucial role in the differentiation potential, particularly along the neural lineage, regulating gene induction and H3 'Lys-4' methylation at key developmental loci, including that mediated by retinoic acid (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"RBBP7":{"hgnc":"HGNC:9890","symbol":"RBBP7","accessions":["Q16576"],"name":"Histone-binding protein RBBP7","length":"425","function":"Core histone-binding subunit that may target chromatin remodeling factors, histone acetyltransferases and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA. Component of several complexes which regulate chromatin metabolism. These include the type B histone acetyltransferase (HAT) complex, which is required for chromatin assembly following DNA replication; the core histone deacetylase (HDAC) complex, which promotes histone deacetylation and consequent transcriptional repression; the nucleosome remodeling and histone deacetylase complex (the NuRD complex), which promotes transcriptional repression by histone deacetylation and nucleosome remodeling; and the PRC2/EED-EZH2 complex, which promotes repression of homeotic genes during development; and the NURF (nucleosome remodeling factor) complex","subunit":"Binds directly to helix 1 of the histone fold of histone H4, a region that is not accessible when H4 is in chromatin (PubMed:18571423, PubMed:9427644). Subunit of the type B histone acetyltransferase (HAT) complex, composed of RBBP7 and HAT1 (PubMed:9427644). Subunit of the core histone deacetylase (HDAC) complex, which is composed of HDAC1, HDAC2, RBBP4 and RBBP7. The core HDAC complex associates with SIN3A, ARID4B/SAP180, SAP18, SAP30, SAP130, SUDS3/SAP45 and possibly ARID4A/RBP1 and ING1 to form the SIN3 HDAC complex (PubMed:11118440, PubMed:11784859, PubMed:9150135, PubMed:9651585). Component of the nucleosome remodeling and deacetylase (NuRD) repressor complex, composed of core proteins MTA1, MTA2, MTA3, RBBP4, RBBP7, HDAC1, HDAC2, MBD2, MBD3, and peripherally associated proteins CDK2AP1, CDK2AP2, GATAD2A, GATAD2B, CHD3, CHD4 and CHD5 (PubMed:10444591, PubMed:11102443, PubMed:16428440, PubMed:28977666, PubMed:33283408, PubMed:9790534). The exact stoichiometry of the NuRD complex is unknown, and some subunits such as MBD2 and MBD3, GATAD2A and GATAD2B, and CHD3, CHD4 and CHD5 define mutually exclusive NuRD complexes (PubMed:16428440, PubMed:28977666, PubMed:33283408). The NuRD complex may interact with MBD3L1 (PubMed:15456747). The NuRD complex may interact with MBD3L2 (PubMed:15701600). Subunit of the PRC2/EED-EZH2 complex, which is composed of at least EED, EZH2, RBBP4, RBBP7 and SUZ12 (PubMed:12435631). The PRC2/EED-EZH2 complex may also associate with HDAC1 (PubMed:12435631). Component of the NURF-1 ISWI chromatin remodeling complex (also called the nucleosome-remodeling factor (NURF) complex) at least composed of SMARCA1 (isoform 2), BPTF, RBBP4 and RBBP7 (PubMed:14609955, PubMed:15310751). Within the complex interacts with isoform 2 of SMARCA1 (PubMed:14609955, PubMed:15310751). Component of the BPFT-SMARCA1 complex at least composed of SMARCA1 (isoform 1), BPFT, RBBP4 and RBBP7; the complex is catalytically inactive and does not remodel chromatin (PubMed:15310751). Within the complex interacts with isoform 1 of SMARCA1 (PubMed:15310751). Interacts with BRCA1 (PubMed:10220405). Interacts with CDK2AP1 (PubMed:20523938). Interacts with CENPA (PubMed:25556658). Interacts with CHD3 (PubMed:28977666). Interacts with CHD4 (PubMed:28977666). Interacts with CREBBP, and this interaction may be enhanced by the binding of phosphorylated CREB1 to CREBBP (PubMed:10866654). Interacts with HDAC7 (By similarity). Interacts with MTA1 (PubMed:12920132). Interacts with PWWP2B (By similarity). Interacts with RB1 (via viral protein-binding domain) (PubMed:10220405, PubMed:7503932). Interacts with SUV39H1 (By similarity)","family":"Belongs to the WD repeat RBAP46/RBAP48/MSI1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10866654","16428440","28977666"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；线粒体/代谢；发育/分化；注释原文：Core histone-binding subunit that may target chromatin remodeling factors, histone acetyltransferases and histone deacetylases to their histone substrates in a manner that is regulated by nucleosomal DNA.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；线粒体/代谢；发育/分化"},"RBBP8NL":{"hgnc":"HGNC:16144","symbol":"RBBP8NL","accessions":["Q8NC74"],"name":"RBBP8 N-terminal-like protein","length":"664","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"RBFOX1":{"hgnc":"HGNC:18222","symbol":"RBFOX1","accessions":["Q9NWB1"],"name":"RNA binding protein fox-1 homolog 1","length":"397","function":"RNA-binding protein that regulates alternative splicing events by binding to 5'-UGCAUGU-3' elements. Regulates alternative splicing of tissue-specific exons and of differentially spliced exons during erythropoiesis","subunit":"Binds to the C-terminus of ATXN2","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16537540"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：RNA-binding protein that regulates alternative splicing events by binding to 5'-UGCAUGU-3' elements.","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"RBFOX2":{"hgnc":"HGNC:9906","symbol":"RBFOX2","accessions":["O43251"],"name":"RNA binding protein fox-1 homolog 2","length":"390","function":"RNA-binding protein that regulates alternative splicing events by binding to 5'-UGCAUGU-3' elements. Prevents binding of U2AF2 to the 3'-splice site. Regulates alternative splicing of tissue-specific exons and of differentially spliced exons during erythropoiesis (By similarity). RNA-binding protein that seems to act as a coregulatory factor of ER-alpha. Together with RNA binding proteins RBPMS and MBNL1/2, activates vascular smooth muscle cells alternative splicing events (PubMed:37548402)","subunit":"Interacts with ER-alpha N-terminal activation domain. Interacts with RBPMS; the interaction allows cooperative assembly of stable cell-specific alternative splicing regulatory complexes (PubMed:37548402)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11875103","37548402"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：RNA-binding protein that regulates alternative splicing events by binding to 5'-UGCAUGU-3' elements.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"未归类"},"RBFOX3":{"hgnc":"HGNC:27097","symbol":"RBFOX3","accessions":["A6NFN3"],"name":"RNA binding protein fox-1 homolog 3","length":"312","function":"Pre-mRNA alternative splicing regulator. Regulates alternative splicing of RBFOX2 to enhance the production of mRNA species that are targeted for nonsense-mediated decay (NMD)","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Pre-mRNA alternative splicing regulator.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接"},"RBM10":{"hgnc":"HGNC:9896","symbol":"RBM10","accessions":["P98175"],"name":"RNA-binding protein 10","length":"930","function":"Binds to ssRNA containing the consensus sequence 5'-AGGUAA-3' (PubMed:21256132). May be involved in post-transcriptional processing, most probably in mRNA splicing (PubMed:18315527). Binds to RNA homopolymers, with a preference for poly(G) and poly(U) and little for poly(A) (By similarity). May bind to specific miRNA hairpins (PubMed:28431233)","subunit":"Associates with the spliceosome. Component of a large chromatin remodeling complex, at least composed of MYSM1, PCAF, RBM10 and KIF11/TRIP5","family":"","domains":[],"function_pmids":["18315527","21256132","28431233"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Binds to ssRNA containing the consensus sequence 5'-AGGUAA-3' (PubMed:21256132). May be involved in post-transcriptional processing, most probably in mRNA splicing (PubMed:18315527). Binds to RNA homopolymers, with a preference for poly(G) and poly(U) and little for poly(A) (By similarity). May bind to specific miRNA hairpins (PubMed:28431233)"},"RBM11":{"hgnc":"HGNC:9897","symbol":"RBM11","accessions":["P57052"],"name":"Splicing regulator RBM11","length":"281","function":"Tissue-specific splicing factor with potential implication in the regulation of alternative splicing during neuron and germ cell differentiation. Antagonizes SRSF1-mediated BCL-X splicing. May affect the choice of alternative 5' splice sites by binding to specific sequences in exons and antagonizing the SR protein SRSF1","subunit":"Homodimer","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21984414"],"location":"Nucleus, nucleoplasm；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Tissue-specific splicing factor with potential implication in the regulation of alternative splicing during neuron and germ cell differentiation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"发育/分化"},"RBM12":{"hgnc":"HGNC:9898","symbol":"RBM12","accessions":["Q9NTZ6"],"name":"RNA-binding protein 12","length":"932","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"RBM12B":{"hgnc":"HGNC:32310","symbol":"RBM12B","accessions":["Q8IXT5"],"name":"RNA-binding protein 12B","length":"1001","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"RBM14":{"hgnc":"HGNC:14219","symbol":"RBM14","accessions":["Q96PK6"],"name":"RNA-binding protein 14","length":"669","function":"Isoform 1 may function as a nuclear receptor coactivator, enhancing transcription through other coactivators such as NCOA6 and CITED1. Isoform 2, functions as a transcriptional repressor, modulating transcriptional activities of coactivators including isoform 1, NCOA6 and CITED1 (PubMed:11443112). Regulates centriole biogenesis by suppressing the formation of aberrant centriolar protein complexes in the cytoplasm and thus preserving mitotic spindle integrity. Prevents the formation of the STIL-CPAP complex (which can induce the formation of aberrant centriolar protein complexes) by interfering with the interaction of STIL with CPAP (PubMed:25385835). Plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728). Also involved in the regulation of pre-mRNA alternative splicing (PubMed:37548402)","subunit":"Isoform 1: Interacts with NCOA6, CITED1 and XRCC5/KU86 (PubMed:11443112). Isoform 1: Interacts with SS18 isoform 1 (PubMed:15919756). Isoform 1: Interacts with SS18 isoform 2 (PubMed:15919756). Interacts with STIL and interferes with its interaction with CPAP. Interacts with gamma-tubulin (PubMed:25385835). Part of the HDP-RNP complex composed of at least HEXIM1, PRKDC, XRCC5, XRCC6, paraspeckle proteins (SFPQ, NONO, PSPC1, RBM14, and MATR3) and NEAT1 RNA. Interacts with RBPMS; the interaction allows cooperative assembly of RNA-bound stable cell-specific alternative splicing regulatory complexes (PubMed:37548402)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11443112","25385835","28712728","37548402"],"location":"Nucleus；Nucleus, nucleolus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Isoform 1 may function as a nuclear receptor coactivator, enhancing transcription through other coactivators such as NCOA6 and CITED1.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"RBM17":{"hgnc":"HGNC:16944","symbol":"RBM17","accessions":["Q96I25"],"name":"Splicing factor 45","length":"401","function":"Splice factor that binds to the single-stranded 3'AG at the exon/intron border and promotes its utilization in the second catalytic step. Involved in the regulation of alternative splicing and the utilization of cryptic splice sites. Promotes the utilization of a cryptic splice site created by the beta-110 mutation in the HBB gene. The resulting frameshift leads to sickle cell anemia","subunit":"Binds SXL. Associates with the spliceosome. Interacts with SF3B1, SF1 and U2AF2","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12015979","17589525"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Splice factor that binds to the single-stranded 3'AG at the exon/intron border and promotes its utilization in the second catalytic step.","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"RBM18":{"hgnc":"HGNC:28413","symbol":"RBM18","accessions":["Q96H35"],"name":"Probable RNA-binding protein 18","length":"190","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"RBM19":{"hgnc":"HGNC:29098","symbol":"RBM19","accessions":["Q9Y4C8"],"name":"Probable RNA-binding protein 19","length":"960","function":"Plays a role in embryo pre-implantation development","subunit":"无可用SUBUNIT段","family":"Belongs to the RRM MRD1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus；Nucleus, nucleoplasm；Cytoplasm；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Plays a role in embryo pre-implantation development","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"发育/分化"},"RBM20":{"hgnc":"HGNC:27424","symbol":"RBM20","accessions":["Q5T481"],"name":"RNA-binding protein 20","length":"1227","function":"RNA-binding protein that acts as a regulator of mRNA splicing of a subset of genes encoding key structural proteins involved in cardiac development, such as TTN (Titin), CACNA1C, CAMK2D or PDLIM5/ENH (PubMed:22466703, PubMed:24960161, PubMed:26604136, PubMed:27496873, PubMed:27531932, PubMed:29895960, PubMed:30948719, PubMed:32840935, PubMed:34732726, PubMed:35427468). Acts as a repressor of mRNA splicing: specifically binds the 5'UCUU-3' motif that is predominantly found within intronic sequences of pre-mRNAs, leading to the exclusion of specific exons in target transcripts (PubMed:24960161, PubMed:30948719, PubMed:34732726). RBM20-mediated exon skipping is hormone-dependent and is essential for TTN isoform transition in both cardiac and skeletal muscles (PubMed:27531932, PubMed:30948719). RBM20-mediated exon skipping of TTN provides substrates for the formation of circular RNA (circRNAs) from the TTN transcripts (PubMed:27531932, PubMed:34732726). Together with RBM24, promotes the expression of short isoforms of PDLIM5/ENH in cardiomyocytes (By similarity)","subunit":"Associates with components of the U1 and U2 U1 small nuclear ribonucleoprotein complexes","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22466703","24960161","26604136","27496873","27531932","29895960","30948719","32840935","34732726","35427468"],"location":"Nucleus；Cytoplasm, Cytoplasmic ribonucleoprotein granule","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；发育/分化；注释原文：RNA-binding protein that acts as a regulator of mRNA splicing of a subset of genes encoding key structural proteins involved in cardiac development, such as TTN (Titin), CACNA1C, CAMK2D or PDLIM5/ENH (PubMed:22466703, PubMed:24960161, PubMed:26604136, PubMed:27496873, PubMed:27531932, PubMed:29895960, PubMed:30948719, PubMed:32840935, PubMed:34732726, PubMed:35427468).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；发育/分化"},"RBM22":{"hgnc":"HGNC:25503","symbol":"RBM22","accessions":["Q9NW64"],"name":"Pre-mRNA-splicing factor RBM22","length":"420","function":"Required for pre-mRNA splicing as component of the activated spliceosome (PubMed:28076346, PubMed:28502770, PubMed:29301961, PubMed:29360106, PubMed:29361316, PubMed:30705154). Involved in the first step of pre-mRNA splicing. Binds directly to the internal stem-loop (ISL) domain of the U6 snRNA and to the pre-mRNA intron near the 5' splice site during the activation and catalytic phases of the spliceosome cycle. Involved in both translocations of the nuclear SLU7 to the cytoplasm and the cytosolic calcium-binding protein PDCD6 to the nucleus upon cellular stress responses","subunit":"Component of the pre-catalytic and catalytic spliceosome complexes (PubMed:11991638, PubMed:28076346, PubMed:28502770, PubMed:29301961, PubMed:29360106, PubMed:29361316). Component of the postcatalytic spliceosome P complex (PubMed:30705154). Interacts with PDCD6; the interaction induces translocation of PDCD6 in the cytoplasm. Interacts with PPIL1 (PubMed:33220177)","family":"Belongs to the SLT11 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17045351","21122810","22246180","28076346","28502770","29301961","29360106","29361316","30705154"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Required for pre-mRNA splicing as component of the activated spliceosome (PubMed:28076346, PubMed:28502770, PubMed:29301961, PubMed:29360106, PubMed:29361316, PubMed:30705154).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"RBM24":{"hgnc":"HGNC:21539","symbol":"RBM24","accessions":["Q9BX46"],"name":"RNA-binding protein 24","length":"236","function":"Multifunctional RNA-binding protein involved in the regulation of pre-mRNA splicing, mRNA stability and mRNA translation important for cell fate decision and differentiation (PubMed:20977548, PubMed:24375645, PubMed:29104163, PubMed:29358667). Plays a major role in pre-mRNA alternative splicing regulation (PubMed:26990106, PubMed:29104163). Mediates preferentially muscle-specific exon inclusion in numerous mRNAs important for striated cardiac and skeletal muscle cell differentiation (PubMed:29104163). Binds to intronic splicing enhancer (ISE) composed of stretches of GU-rich motifs localized in flanking intron of exon that will be included by alternative splicing (By similarity). Involved in embryonic stem cell (ESC) transition to cardiac cell differentiation by promoting pre-mRNA alternative splicing events of several pluripotency and/or differentiation genes (PubMed:26990106). Plays a role in the regulation of mRNA stability (PubMed:20977548, PubMed:24356969, PubMed:24375645, PubMed:29104163). Binds to 3'-untranslated region (UTR) AU-rich elements in target transcripts, such as CDKN1A and MYOG, leading to maintain their stabilities (PubMed:20977548, PubMed:24356969). Involved in myogenic differentiation by regulating MYOG levels (PubMed:20977548). Binds to multiple regions in the mRNA 3'-UTR of TP63 isoform 2, hence inducing its destabilization (PubMed:24375645). Also promotes the destabilization of the CHRM2 mRNA via its binding to a region in the coding sequence (PubMed:29104163). Plays a role in the regulation of mRNA translation (PubMed:29358667). Mediates repression of p53/TP53 mRNA translation through its binding to U-rich element in the 3'-UTR, hence preventing EIF4E from binding to p53/TP53 mRNA and translation initiation (PubMed:29358667). Binds to a huge amount of mRNAs (PubMed:29104163). Required for embryonic heart development, sarcomer and M-band formation in striated muscles (By similarity). Together with RBM20, promotes the expression of short isoforms of PDLIM5/ENH in cardiomyocytes (By similarity)\n(Microbial infection) Promotes hepatitis C virus (HCV) replication over translation through the inhibition of viral protein expression. Decreases viral translation by linking viral 5'- and 3'-UTRs, blocking 80S ribosome assembly on the viral IRES and enhancing the interaction of the mature core protein and 5'-UTR","subunit":"Interacts with EIF4E; this interaction prevents EIF4E from binding to p53/TP53 mRNA and inhibits the assembly of translation initiation complex (PubMed:29358667)\n(Microbial infection) Interacts with HCV mature core protein; this interaction, which enhances the interaction of Core with 5'-UTR may favor viral replication over translation\n(Microbial infection) Interacts with HCV Serine protease/helicase NS3","family":"","domains":[],"function_pmids":["20977548","24356969","24375645","26990106","29104163","29358667","29380205"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Multifunctional RNA-binding protein involved in the regulation of pre-mRNA splicing, mRNA stability and mRNA translation important for cell fate decision and differentiation (PubMed:20977548, PubMed:24375645, PubMed:29104163, PubMed:29358667). Plays a major role in pre-mRNA alternative splicing regulation (PubMed:26990106, PubMed:29104163). Mediates preferentially muscle-specific exon inclusion in numerous mRNAs important for striated cardiac and skeletal muscle cell differentiation (PubMed:29104163). Binds to intronic splicing enhancer (ISE) composed of stretches of GU-rich motifs localized in flanking intron of exon that will be included by alternative splicing (By similarity). Involved in embryonic stem cell (ESC) transition to cardiac cell differentiation by promoting pre-mRNA alternative splicing events of several pluripotency and/or differentiation genes (PubMed:26990106). Plays a role in the regulation of mRNA stability (PubMed:20977548, PubMed:24356969, PubMed:24375645, PubMed:29104163). Binds to 3'-untranslated region (UTR) AU-rich elements in target transcripts, such as CDKN1A and MYOG, leading to maintain their stabilities (PubMed:20977548, PubMed:24356969). Involved in myogenic differentiation by regulating MYOG levels (PubMed:20977548). Binds to multiple regions in the mRNA 3'-UTR of TP63 isoform 2, hence inducing its destabilization (PubMed:24375645). Also promotes the destabilization of the CHRM2 mRNA via its binding to a region in the coding sequence (PubMed:29104163). Plays a role in the regulation of mRNA translation (PubMed:29358667). Mediates repression of p53/TP53 mRNA translation through its binding to U-rich element in the 3'-UTR, hence preventing EIF4E from binding to p53/TP53 mRNA and translation initiation (PubMed:29358667). Binds to a huge amount of mRNAs (PubMed:29104163). Required for embryonic heart development, sarcomer and M-band formation in striated muscles (By similarity). Together with RBM20, promotes the expression of short isoforms of PDLIM5/ENH in cardiomyocytes (By similarity)\n(Microbial infection) Promotes hepatitis C virus (HCV) replication over translation through the inhibition of viral protein expression. Decreases viral translation by linking viral 5'- and 3'-UTRs, blocking 80S ribosome assembly on the viral IRES and enhancing the interaction of the mature core protein and 5'-UTR"},"RBM27":{"hgnc":"HGNC:29243","symbol":"RBM27","accessions":["Q9P2N5"],"name":"RNA-binding protein 27","length":"1060","function":"May be involved in the turnover of nuclear polyadenylated (pA+) RNA","subunit":"","family":"","domains":[],"function_pmids":["31950173"],"location":"Cytoplasm; Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May be involved in the turnover of nuclear polyadenylated (pA+) RNA"},"RBM28":{"hgnc":"HGNC:21863","symbol":"RBM28","accessions":["Q9NW13"],"name":"RNA-binding protein 28","length":"759","function":"Nucleolar component of the spliceosomal ribonucleoprotein complexes","subunit":"Interacts with U1, U2, U4, U5, and U6 spliceosomal small nuclear RNAs (snRNAs)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17081119"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Nucleolar component of the spliceosomal ribonucleoprotein complexes","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"RBM3":{"hgnc":"HGNC:9900","symbol":"RBM3","accessions":["P98179"],"name":"RNA-binding protein 3","length":"157","function":"Cold-inducible mRNA binding protein that enhances global protein synthesis at both physiological and mild hypothermic temperatures. Reduces the relative abundance of microRNAs, when overexpressed. Enhances phosphorylation of translation initiation factors and active polysome formation (By similarity)","subunit":"Interacts with RPL4. Associates with the 60S ribosomal subunits in an RNA-independent manner. Associates with ribosomes (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm；Cell projection, dendrite","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；翻译/核糖体；注释原文：Cold-inducible mRNA binding protein that enhances global protein synthesis at both physiological and mild hypothermic temperatures.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"激酶/磷酸化信号；翻译/核糖体"},"RBM33":{"hgnc":"HGNC:27223","symbol":"RBM33","accessions":["Q96EV2"],"name":"RNA-binding protein 33","length":"1170","function":"RNA reader protein, which recognizes and binds specific RNAs, thereby regulating RNA metabolic processes, such as mRNA export, mRNA stability and/or translation (PubMed:35589130, PubMed:37257451). Binds a subset of intronless RNAs containing GC-rich elements, such as NORAD, and promotes their nuclear export by recruiting target RNAs to components of the NXF1-NXT1 RNA export machinery (PubMed:35589130). Specifically recognizes and binds N6-methyladenosine (m6A)-containing mRNAs, promoting their demethylation by ALKBH5 (PubMed:37257451). Acts as an molecular adapter, which (1) promotes ALKBH5 recruitment to m6A-containing transcripts and (2) activates ALKBH5 demethylase activity by recruiting SENP1, leading to ALKBH5 deSUMOylation and subsequent activation (PubMed:37257451)","subunit":"Associates with the NXF1-NXT1 RNA export complex (PubMed:35589130). Interacts with ALKBH5; facilitating ALKBH5 recruitment to m6A-containing transcripts (PubMed:37257451). Interacts with SENP1; promoting ALKBH5 deSUMOylation and subsequent activation (PubMed:37257451)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["35589130","37257451"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；翻译/核糖体；线粒体/代谢；注释原文：RNA reader protein, which recognizes and binds specific RNAs, thereby regulating RNA metabolic processes, such as mRNA export, mRNA stability and/or translation (PubMed:35589130, PubMed:37257451).","function_evidence":"含实验支持条目；ECO:0000269","categories":"核质运输；翻译/核糖体；线粒体/代谢"},"RBM34":{"hgnc":"HGNC:28965","symbol":"RBM34","accessions":["P42696"],"name":"RNA-binding protein 34","length":"430","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the RRM RBM34 family","domains":"Domain 185-280: RRM 1 [ECO:0000255/PROSITE-ProRule/PRU00176]\nDomain 287-364: RRM 2 [ECO:0000255/PROSITE-ProRule/PRU00176]","function_pmids":[],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"RBM39":{"hgnc":"HGNC:15923","symbol":"RBM39","accessions":["Q14498"],"name":"RNA-binding protein 39","length":"530","function":"RNA-binding protein that acts as a pre-mRNA splicing factor (PubMed:15694343, PubMed:24795046, PubMed:28302793, PubMed:28437394, PubMed:31271494). Acts by promoting exon inclusion via regulation of exon cassette splicing (PubMed:31271494). Also acts as a transcriptional coactivator for steroid nuclear receptors ESR1/ER-alpha and ESR2/ER-beta, and JUN/AP-1, independently of the pre-mRNA splicing factor activity (By similarity)","subunit":"Interacts with NCOA6 and JUN. Interacts with ESR1 and ESR2, in the presence of estradiol (E2) (By similarity). Interacts with RSRC1 (via Arg/Ser-rich domain) (PubMed:15798186). Interacts with SF3B1 (PubMed:24795046). Interacts with ZNF106 (via N-terminus) (By similarity)","family":"Belongs to the splicing factor SR family","domains":[],"function_pmids":["15694343","24795046","28302793","28437394","31271494"],"location":"Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"RNA-binding protein that acts as a pre-mRNA splicing factor (PubMed:15694343, PubMed:24795046, PubMed:28302793, PubMed:28437394, PubMed:31271494). Acts by promoting exon inclusion via regulation of exon cassette splicing (PubMed:31271494). Also acts as a transcriptional coactivator for steroid nuclear receptors ESR1/ER-alpha and ESR2/ER-beta, and JUN/AP-1, independently of the pre-mRNA splicing factor activity (By similarity)"},"RBM4":{"hgnc":"HGNC:9901","symbol":"RBM4","accessions":["Q9BWF3"],"name":"RNA-binding protein 4","length":"364","function":"RNA-binding factor involved in multiple aspects of cellular processes like alternative splicing of pre-mRNA and translation regulation. Modulates alternative 5'-splice site and exon selection. Acts as a muscle cell differentiation-promoting factor. Activates exon skipping of the PTB pre-mRNA during muscle cell differentiation. Antagonizes the activity of the splicing factor PTBP1 to modulate muscle cell-specific exon selection of alpha tropomyosin. Binds to intronic pyrimidine-rich sequence of the TPM1 and MAPT pre-mRNAs. Required for the translational activation of PER1 mRNA in response to circadian clock. Binds directly to the 3'-UTR of the PER1 mRNA. Exerts a suppressive activity on Cap-dependent translation via binding to CU-rich responsive elements within the 3'UTR of mRNAs, a process increased under stress conditions or during myocytes differentiation. Recruits EIF4A1 to stimulate IRES-dependent translation initiation in respons to cellular stress. Associates to internal ribosome entry segment (IRES) in target mRNA species under stress conditions. Plays a role for miRNA-guided RNA cleavage and translation suppression by promoting association of AGO2-containing miRNPs with their cognate target mRNAs. Associates with miRNAs during muscle cell differentiation. Binds preferentially to 5'-CGCGCG[GCA]-3' motif in vitro","subunit":"Interacts with TNPO3; the interaction mediates nuclear import of the protein and is disrupted by nuclear Ran bound to GTP. Interacts with EIF4G1 and WT1. Interacts with EIF4A1; the interaction is modulated under stress-induced conditions. Interacts with AGO1. Interacts with AGO2; the interaction occurs under both cell proliferation and differentiation conditions and in an RNA- and phosphorylation-independent manner. Interacts with DDX5; the interaction occurs in an RNA-independent manner. Interacts with RBPMS; the interaction allows cooperative assembly of RNA-bound stable cell-specific alternative splicing regulatory complexes (PubMed:37548402)","family":"","domains":[],"function_pmids":["12628928","16260624","16777844","16934801","17284590","17932509","19801630","21343338","21518792","37548402"],"location":"Nucleus; Nucleus, nucleolus; Nucleus speckle; Cytoplasm; Cytoplasmic granule","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"RNA-binding factor involved in multiple aspects of cellular processes like alternative splicing of pre-mRNA and translation regulation. Modulates alternative 5'-splice site and exon selection. Acts as a muscle cell differentiation-promoting factor. Activates exon skipping of the PTB pre-mRNA during muscle cell differentiation. Antagonizes the activity of the splicing factor PTBP1 to modulate muscle cell-specific exon selection of alpha tropomyosin. Binds to intronic pyrimidine-rich sequence of the TPM1 and MAPT pre-mRNAs. Required for the translational activation of PER1 mRNA in response to circadian clock. Binds directly to the 3'-UTR of the PER1 mRNA. Exerts a suppressive activity on Cap-dependent translation via binding to CU-rich responsive elements within the 3'UTR of mRNAs, a process increased under stress conditions or during myocytes differentiation. Recruits EIF4A1 to stimulate IRES-dependent translation initiation in respons to cellular stress. Associates to internal ribosome entry segment (IRES) in target mRNA species under stress conditions. Plays a role for miRNA-guided RNA cleavage and translation suppression by promoting association of AGO2-containing miRNPs with their cognate target mRNAs. Associates with miRNAs during muscle cell differentiation. Binds preferentially to 5'-CGCGCG[GCA]-3' motif in vitro"},"RBM42":{"hgnc":"HGNC:28117","symbol":"RBM42","accessions":["Q9BTD8"],"name":"RNA-binding protein 42","length":"480","function":"Binds (via the RRM domain) to the 3'-untranslated region (UTR) of CDKN1A mRNA","subunit":"Interacts with HNRNPK","family":"Belongs to the RRM RBM42 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Binds (via the RRM domain) to the 3'-untranslated region (UTR) of CDKN1A mRNA","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"未归类"},"RBM45":{"hgnc":"HGNC:24468","symbol":"RBM45","accessions":["Q8IUH3"],"name":"RNA-binding protein 45","length":"476","function":"RNA-binding protein with binding specificity for poly(C). May play an important role in neural development","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12220514"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：RNA-binding protein with binding specificity for poly(C).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"发育/分化"},"RBM47":{"hgnc":"HGNC:30358","symbol":"RBM47","accessions":["A0AV96"],"name":"RNA-binding protein 47","length":"593","function":"Single-stranded RNA-binding protein that functions in a variety of RNA processes, including alternative splicing, RNA stabilization, and RNA editing (PubMed:24038582, PubMed:24916387, PubMed:27050523, PubMed:30844405, PubMed:31358901, PubMed:34160127). Functions as an enzyme-substrate adapter for the cytidine deaminase APOBEC1. With APOBEC1 forms an mRNA editing complex involved into cytidine to uridine editing of a variety of mRNA molecules (PubMed:24038582, PubMed:24916387, PubMed:30844405). Through the binding of their 3'UTR, also stabilizes a variety of mRNAs and regulates the expression of genes such as the interferon alpha/beta receptor and interleukin-10 (PubMed:34160127). Also involved in the alternative splicing of several genes including TJP1. Binds the pre-mRNA (U)GCAUG consensus sequences in downstream intronic regions of alternative exons, regulating their exclusion and inclusion into mRNAs (PubMed:27050523, PubMed:31358901). Independently of its RNA-binding activity, could negatively regulate MAVS by promoting its lysosomal degradation (By similarity)","subunit":"Homodimer (PubMed:31358901). Interacts with A1CF (PubMed:24916387). Interacts with APOBEC1; form an mRNA editing complex (PubMed:24916387). Interacts with RBPMS (PubMed:37548402)","family":"Belongs to the RRM RBM47 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["24038582","24916387","27050523","30844405","31358901","34160127"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Single-stranded RNA-binding protein that functions in a variety of RNA processes, including alternative splicing, RNA stabilization, and RNA editing (PubMed:24038582, PubMed:24916387, PubMed:27050523, PubMed:30844405, PubMed:31358901, PubMed:34160127).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"RBM48":{"hgnc":"HGNC:21785","symbol":"RBM48","accessions":["Q5RL73"],"name":"RNA-binding protein 48","length":"367","function":"As a component of the minor spliceosome, involved in the splicing of U12-type introns in pre-mRNAs","subunit":"Component of the minor spliceosome. Within this complex, interacts with ARMC7 and PRPF8/PRP8","family":"Belongs to the RBM48 family","domains":[],"function_pmids":["33509932"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"As a component of the minor spliceosome, involved in the splicing of U12-type introns in pre-mRNAs"},"RBM4B":{"hgnc":"HGNC:28842","symbol":"RBM4B","accessions":["Q9BQ04"],"name":"RNA-binding protein 4B","length":"359","function":"Required for the translational activation of PER1 mRNA in response to circadian clock. Binds directly to the 3'-UTR of the PER1 mRNA (By similarity)","subunit":"Interacts with TNPO3, which may mediate nuclear import of the protein","family":"","domains":[],"function_pmids":[],"location":"Nucleus; Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Required for the translational activation of PER1 mRNA in response to circadian clock. Binds directly to the 3'-UTR of the PER1 mRNA (By similarity)"},"RBM6":{"hgnc":"HGNC:9903","symbol":"RBM6","accessions":["P78332"],"name":"RNA-binding protein 6","length":"1123","function":"Specifically binds poly(G) RNA homopolymers in vitro","subunit":"May interact with FAM168B","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Specifically binds poly(G) RNA homopolymers in vitro","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"RBM7":{"hgnc":"HGNC:9904","symbol":"RBM7","accessions":["Q9Y580"],"name":"RNA-binding protein 7","length":"266","function":"RNA-binding subunit of the trimeric nuclear exosome targeting (NEXT) complex, a complex that functions as an RNA exosome cofactor that directs a subset of non-coding short-lived RNAs for exosomal degradation (PubMed:25189701, PubMed:25525152, PubMed:25578728, PubMed:25852104, PubMed:27871484). NEXT is involved in surveillance and turnover of aberrant transcripts and non-coding RNAs (PubMed:25189701, PubMed:25852104, PubMed:27871484). Binds preferentially polyuridine sequences and associates with newly synthesized RNAs, including pre-mRNAs and short-lived exosome substrates such as promoter upstream transcripts (PROMPTs), enhancer RNAs (eRNAs), and 3'-extended products from small nuclear RNAs (snRNAs) (PubMed:25189701, PubMed:25525152, PubMed:25578728, PubMed:25852104). Participates in several biological processes including DNA damage response (DDR) and stress response (PubMed:25525152, PubMed:30824372). During stress response, activation of the p38MAPK-MK2 pathway decreases RBM7-RNA-binding and subsequently the RNA exosome degradation activities, thereby modulating the turnover of non-coding transcriptome (PubMed:25525152). Participates in DNA damage response (DDR), through its interaction with MEPCE and LARP7, the core subunits of 7SK snRNP complex, that release the positive transcription elongation factor b (P-TEFb) complex from the 7SK snRNP. In turn, activation of P-TEFb complex induces the transcription of P-TEFb-dependent DDR genes to promote cell viability (PubMed:30824372)","subunit":"Component of the nuclear exosome targeting (NEXT) complex composed of MTREX, ZCCHC8, and RBM7 that directs a subset of non-coding short-lived RNAs for exosomal degradation (PubMed:25189701, PubMed:27871484, PubMed:27905398). Interacts with ZCCHC8 and SF3B2/SAP145 (PubMed:16263084, PubMed:27871484, PubMed:27905398). Binds to MTREX through ZCCHC8 (PubMed:27871484). Interacts with YWHAE and YWHAZ; these interactions are stress-dependent and RBM7 phosphorylation dependent; release RNA from the NEXT complex and may affect RNA targeting to the nuclear RNA exosomome for degradation (PubMed:25189701). Interacts with MEPCE and LARP7, the core subunits of 7SK snRNP; upon genotoxic stress this interaction is enhanced, triggering the release of inactive P-TEFb complex from the core and P-TEFb complex activation (PubMed:30824372)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25189701","25525152","25578728","25852104","27871484","30824372"],"location":"Nucleus, nucleoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；注释原文：RNA-binding subunit of the trimeric nuclear exosome targeting (NEXT) complex, a complex that functions as an RNA exosome cofactor that directs a subset of non-coding short-lived RNAs for exosomal degradation (PubMed:25189701, PubMed:25525152, PubMed:25578728, PubMed:25852104, PubMed:27871484).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制"},"RBM8A":{"hgnc":"HGNC:9905","symbol":"RBM8A","accessions":["Q9Y5S9"],"name":"RNA-binding protein 8A","length":"174","function":"Required for pre-mRNA splicing as component of the spliceosome (PubMed:28502770, PubMed:29301961). Core component of the splicing-dependent multiprotein exon junction complex (EJC) deposited at splice junctions on mRNAs. The EJC is a dynamic structure consisting of core proteins and several peripheral nuclear and cytoplasmic associated factors that join the complex only transiently either during EJC assembly or during subsequent mRNA metabolism. The EJC marks the position of the exon-exon junction in the mature mRNA for the gene expression machinery and the core components remain bound to spliced mRNAs throughout all stages of mRNA metabolism thereby influencing downstream processes including nuclear mRNA export, subcellular mRNA localization, translation efficiency and nonsense-mediated mRNA decay (NMD). The MAGOH-RBM8A heterodimer inhibits the ATPase activity of EIF4A3, thereby trapping the ATP-bound EJC core onto spliced mRNA in a stable conformation. The MAGOH-RBM8A heterodimer interacts with the EJC key regulator PYM1 leading to EJC disassembly in the cytoplasm and translation enhancement of EJC-bearing spliced mRNAs by recruiting them to the ribosomal 48S preinitiation complex. Its removal from cytoplasmic mRNAs requires translation initiation from EJC-bearing spliced mRNAs. Associates preferentially with mRNAs produced by splicing. Does not interact with pre-mRNAs, introns, or mRNAs produced from intronless cDNAs. Associates with both nuclear mRNAs and newly exported cytoplasmic mRNAs. The MAGOH-RBM8A heterodimer is a component of the nonsense mediated decay (NMD) pathway. Involved in the splicing modulation of BCL2L1/Bcl-X (and probably other apoptotic genes); specifically inhibits formation of proapoptotic isoforms such as Bcl-X(S); the function is different from the established EJC assembly","subunit":"Heterodimer with either MAGOH or MAGOHB (PubMed:10662555, PubMed:12730685, PubMed:12781131, PubMed:23917022). Part of the mRNA splicing-dependent exon junction complex (EJC) complex; the core complex contains CASC3, EIF4A3, MAGOH or MAGOHB, and RBM8A (PubMed:11707413, PubMed:16170325, PubMed:16314458, PubMed:16923391, PubMed:16931718, PubMed:19033377, PubMed:20479275, PubMed:23917022). Component of the ALYREF/THOC4-EJC-RNA complex; in the complex interacts with EIF4A3 and MAGOH; these interactions are likely specific to RNA-bound EJC (PubMed:16314458, PubMed:37020021). Interacts with PYM1; the interaction is direct and dissociates the EJC from spliced mRNAs (PubMed:14968132, PubMed:18026120, PubMed:19410547). Part of a complex that contains the EJC core components CASC3, EIF4A3, MAGOH and RBM8A plus proteins involved in nonsense-mediated mRNA decay, such as UPF1, UPF2, UPF3A and UPF3B (PubMed:11546873, PubMed:12718880, PubMed:20479275). Found in a post-splicing complex with NXF1, MAGOH, UPF1, UPF2, UPF3A, UPF3B and RNPS1 (PubMed:11546874). Interacts with DDX39B, MAGOH, DPH1, UPF3B, RNPS1, SRRM1 and ALYREF/THOC4 (PubMed:11013075, PubMed:11118221, PubMed:11707413, PubMed:12944400). Interacts with IPO13; the interaction mediates the nuclear import of the MAGOH-RBM8A heterodimer (PubMed:11447110). Identified in the spliceosome C complex (PubMed:11991638, PubMed:28502770, PubMed:29301961). Associates with polysomes (PubMed:12121612)","family":"Belongs to the RBM8A family","domains":[],"function_pmids":["12121612","12718880","12730685","16209946","19409878","22203037","28502770","29301961"],"location":"Nucleus; Nucleus speckle; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Required for pre-mRNA splicing as component of the spliceosome (PubMed:28502770, PubMed:29301961). Core component of the splicing-dependent multiprotein exon junction complex (EJC) deposited at splice junctions on mRNAs. The EJC is a dynamic structure consisting of core proteins and several peripheral nuclear and cytoplasmic associated factors that join the complex only transiently either during EJC assembly or during subsequent mRNA metabolism. The EJC marks the position of the exon-exon junction in the mature mRNA for the gene expression machinery and the core components remain bound to spliced mRNAs throughout all stages of mRNA metabolism thereby influencing downstream processes including nuclear mRNA export, subcellular mRNA localization, translation efficiency and nonsense-mediated mRNA decay (NMD). The MAGOH-RBM8A heterodimer inhibits the ATPase activity of EIF4A3, thereby trapping the ATP-bound EJC core onto spliced mRNA in a stable conformation. The MAGOH-RBM8A heterodimer interacts with the EJC key regulator PYM1 leading to EJC disassembly in the cytoplasm and translation enhancement of EJC-bearing spliced mRNAs by recruiting them to the ribosomal 48S preinitiation complex. Its removal from cytoplasmic mRNAs requires translation initiation from EJC-bearing spliced mRNAs. Associates preferentially with mRNAs produced by splicing. Does not interact with pre-mRNAs, introns, or mRNAs produced from intronless cDNAs. Associates with both nuclear mRNAs and newly exported cytoplasmic mRNAs. The MAGOH-RBM8A heterodimer is a component of the nonsense mediated decay (NMD) pathway. Involved in the splicing modulation of BCL2L1/Bcl-X (and probably other apoptotic genes); specifically inhibits formation of proapoptotic isoforms such as Bcl-X(S); the function is different from the established EJC assembly"},"RBMS1":{"hgnc":"HGNC:9907","symbol":"RBMS1","accessions":["P29558"],"name":"RNA-binding motif, single-stranded-interacting protein 1","length":"406","function":"Single-stranded DNA binding protein that interacts with the region upstream of the MYC gene. Binds specifically to the DNA sequence motif 5'-[AT]CT[AT][AT]T-3'. Probably has a role in DNA replication","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；注释原文：Single-stranded DNA binding protein that interacts with the region upstream of the MYC gene.","function_evidence":"数据库整理/推断；按原文限定；","categories":"DNA修复/复制"},"RBMS2":{"hgnc":"HGNC:9909","symbol":"RBMS2","accessions":["Q15434"],"name":"RNA-binding motif, single-stranded-interacting protein 2","length":"407","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"RBMX":{"hgnc":"HGNC:9910","symbol":"RBMX","accessions":["P38159"],"name":"RNA-binding motif protein, X chromosome","length":"391","function":"RNA-binding protein that plays several role in the regulation of pre- and post-transcriptional processes. Implicated in tissue-specific regulation of gene transcription and alternative splicing of several pre-mRNAs. Binds to and stimulates transcription from the tumor suppressor TXNIP gene promoter; may thus be involved in tumor suppression. When associated with SAFB, binds to and stimulates transcription from the SREBF1 promoter. Associates with nascent mRNAs transcribed by RNA polymerase II. Component of the supraspliceosome complex that regulates pre-mRNA alternative splice site selection. Can either activate or suppress exon inclusion; acts additively with TRA2B to promote exon 7 inclusion of the survival motor neuron SMN2. Represses the splicing of MAPT/Tau exon 10. Binds preferentially to single-stranded 5'-CC[A/C]-rich RNA sequence motifs localized in a single-stranded conformation; probably binds RNA as a homodimer. Binds non-specifically to pre-mRNAs. Also plays a role in the cytoplasmic TNFR1 trafficking pathways; promotes both the IL-1-beta-mediated inducible proteolytic cleavage of TNFR1 ectodomains and the release of TNFR1 exosome-like vesicles to the extracellular compartment","subunit":"Homomultimer. Interacts with SAFB/SAFB1 (By similarity). Found in the supraspliceosome complex. Identified in the spliceosome C complex. Interacts with KHDRBS3. Forms a complex with ILF2, ILF3, YLPM1, KHDRBS1, NCOA5 and PPP1CA. Interacts with CLK2, KHDRBS2, SAFB, TRA2B and YTHDC1. Interacts with ERAP1; the interaction is RNA-independent (PubMed:18445477). Interacts with PPIA/CYPA (PubMed:25678563)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12165565","12761049","16707624","18445477","18541147","19282290","21327109"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：RNA-binding protein that plays several role in the regulation of pre- and post-transcriptional processes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；膜运输/高尔基/内吞；黏附/受体/细胞表面"},"RBMX2":{"hgnc":"HGNC:24282","symbol":"RBMX2","accessions":["Q9Y388"],"name":"RNA-binding motif protein, X-linked 2","length":"322","function":"Involved in pre-mRNA splicing as component of the activated spliceosome. As a component of the minor spliceosome, involved in the splicing of U12-type introns in pre-mRNAs (Probable)","subunit":"Part of the activated spliceosome B/catalytic step 1 spliceosome, one of the forms of the spliceosome which has a well-formed active site but still cannot catalyze the branching reaction and is composed of at least 52 proteins, the U2, U5 and U6 snRNAs and the pre-mRNA. Component of the minor spliceosome, which splices U12-type introns (PubMed:33509932)","family":"Belongs to the IST3 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29360106","29361316","33509932"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in pre-mRNA splicing as component of the activated spliceosome.","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"RNA加工/剪接"},"RBMXL1":{"hgnc":"HGNC:25073","symbol":"RBMXL1","accessions":["Q96E39"],"name":"RNA binding motif protein, X-linked-like-1","length":"390","function":"RNA-binding protein which may be involved in pre-mRNA splicing","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：RNA-binding protein which may be involved in pre-mRNA splicing","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接"},"RBMXL2":{"hgnc":"HGNC:17886","symbol":"RBMXL2","accessions":["O75526"],"name":"RNA-binding motif protein, X-linked-like-2","length":"392","function":"RNA-binding protein involved in alternative splicing in the testis during spermatogenesis","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19893608"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：RNA-binding protein involved in alternative splicing in the testis during spermatogenesis","function_evidence":"含实验支持条目；ECO:0000269","categories":"发育/分化"},"RBMY1A1":{"hgnc":"HGNC:9912","symbol":"RBMY1A1","accessions":["P0DJD3"],"name":"RNA-binding motif protein, Y chromosome, family 1 member A1","length":"496","function":"RNA-binding protein involved in pre-mRNA splicing. Required for sperm development. Acts additively with TRA2B to promote exon 7 inclusion of the survival motor neuron SMN. Binds non-specifically to mRNAs","subunit":"Interacts with splicing factor proteins SFRS3/SRP20, TRA2B/SFRS10, KHDRBS1/SAM68 and KHDRBS3","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12165565","8269511"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；发育/分化；注释原文：RNA-binding protein involved in pre-mRNA splicing.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；发育/分化"}};
